INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd4-ochen-krasivo',
  'Очень красиво',
  (SELECT id FROM "Authors" WHERE name = 'Олег Золотарь' ORDER BY id LIMIT 1),
  'mrd4/mrd4-ochen-krasivo.jpg',
  'data:image/jpeg;base64,',
  1586,
  1119,
  'Тот день я хорошо запомнил. Запомнил в самых мельчайших подробностях. И неудивительно. Ведь это был самый важный день в моей жизни. Самый важный. Вот прямо самый.',
  '[{"kind":"image","path":"mrd4/mrd4-ochen-krasivo.jpg","caption":null},{"kind":"paragraph","text":"Тот день я хорошо запомнил. Запомнил в самых мельчайших подробностях. И неудивительно. Ведь это был самый важный день в моей жизни. Самый важный. Вот прямо самый."},{"kind":"paragraph","text":"Жили мы тогда с отцом у бабули с дедулей. На постоянной основе жили, хотя и считалось, что временно. Дом низколобый и сейчас перед глазами стоит: сени, четыре комнаты, образа по углам, кусты алкоголий у крыльца."},{"kind":"paragraph","text":"Цветы почему-то особенно в память врезались. Тёмно-зелёные стебли, жёлтые бутоны с крупными лепестками, капельками росы. Красивые цветы. Очень красивые. За ними бабуля всё увивалась — лишь бы не засохли, лишь бы не вымерзли. Столько заботы на них перевела, что для прочей жизни и вовсе не осталось."},{"kind":"paragraph","text":"Строгая бабуля была. За словом в карман не лезла, в ответ церемоний не требовала. Вот и в тот самый день — всё цветы подвязывала да отца материла. Крепко материла, самыми последними словами. За жизнь его недалёкую, за то, что только хуем о перспективах думает, за то, что раньше их семья зажиточной считалась и уважением пользовалась, а нынче люди разве что головами при встрече кивают. И ведь не поймёшь, что у этих людей на уме. Но вряд ли что-то хорошее. А всё из-за отца. Из-за него. Только из-за него."},{"kind":"paragraph","text":"Отец на брюзжание бабули внимания не обращал, со двора собирался. В широкой шляпе, лёгких туфлях парусиновых. Улыбался, усы расчёсывал, мне подмигивал."},{"kind":"paragraph","text":"— Погода хороша! Сегодня все красавицы у окон будут да на крыльце! Скоро мамку тебе новую приведу! Хочешь? Хочешь новую мамку?"},{"kind":"paragraph","text":"Я на лавке сидел, отцу не отвечал, хмурился. Знал, чем всё закончится. Временами и вправду приводил блядей, жизнь с дешёвой тушью перепутавших. На день-другой задерживались, редко дольше. Да и не каждый раз подобное отцу удавалось. Чаще один приползал, под утро, соплями по земле. Страдал день-другой чувствами неразделёнными, а после снова — на выгул."},{"kind":"paragraph","text":"Лишь только отец калиткой хлопнул, из виду скрылся, бабуля за кур принялась. Созвала, собрала пернатых вокруг себя, вздохнула тяжко. Ох, больны куры! Очень больны! Жрут, кудахчут, а яиц не несут!"},{"kind":"paragraph","text":"Вот и решила бабуля аспирином их отпоить, чтобы пропотели они и поправились. Словит куру, между колен зафиксирует, одной рукой клюв приоткроет и прямо в горло испуганному пернатому существу микстуру вливает. Вливает, а сама на меня косится."},{"kind":"paragraph","text":"— На батьку дуешься? Ну дуйся, дуйся! Вырастешь — сам таким же будешь!"},{"kind":"paragraph","text":"Закипели мои мысли горькими клятвами: усов таких себе не отращу, шляпы с полями не надену. Да и не отец он мне вовсе! Не отец! Какой же отец, если всегда от нас с мамой уходил? Даже когда ещё в городе жили. Встанет утром, на балкон выйдет. «Хорошо-то как! — скажет. — Погода!» А потом оденется и уйдёт. Когда вернётся — неизвестно. Но обязательно пьяный, в помаде и без денег."},{"kind":"paragraph","text":"Мать не перечила — смирилась к тому времени. Компот часто варила яблочный. Я не любил, но пил. Наверное, чтобы мать не расстраивать."},{"kind":"paragraph","text":"— Вот и ты таким будешь! Ровно таким же! — бабуля сказала, птицу очередную оздоравливая."},{"kind":"paragraph","text":"— Хуй тебе! Хуй угадала! — не сдержался я. — Не буду таким, как этот! Да и не отец он мне, слышишь?! Не отец!"},{"kind":"paragraph","text":"Бабуля в ответ улыбнулась только."},{"kind":"paragraph","text":"— Отец, не отец... Мордами-то одинаковы! А морды с судьбой всегда переплетаются."},{"kind":"paragraph","text":"— На свою морду лучше посмотри!"},{"kind":"paragraph","text":"С лавки вскочил, ведро пустое ногой подфутболил, кур испугал, в дом убежал. Долго после отдышаться не мог. Понимал, что к реке после подобных восклицаний не отпустят. И без того редко отпускали. Всё боялись, что утоплюсь. Сам слышал не раз, как за спиной моей шептались: мол, если к реке отпустить — обязательно утопится. Утопится, как пить дать! И что потом люди подумают?"},{"kind":"paragraph","text":"Шептались, надо сказать, не просто так, не из вымысла. Я и вправду несколько раз топиться убегал. Но только давно, когда из города сюда переехали. Почему-то казалось мне, что утопиться — идея в самый раз. Но так и не утопился. Однажды в воду зашёл и понял, что не в смерти дело, а в жизни. А раз так, то и мешать их воедино смысла нет."},{"kind":"paragraph","text":"Но бабе объяснять подобное смысла не было. Знал, что не поверит. Кроме Бога вообще никому не верила, хотя Бог у неё какой-то очень странный получался — всё знал, всё видел, всё мог, но при этом не считал нужным вмешиваться в судьбы человеческие. Мол, как проживёте — так с вас и спрошу. Я даже интересовался у бабули: зачем верить в такого Бога? Какое ему дело до нас? И какой в таком случае с нас может быть спрос? Но ответа так и не дождался."},{"kind":"paragraph","text":"А дома делать нечего — тоска, полумрак, сожаления."},{"kind":"paragraph","text":"К деду в комнату заглянул, воды стакан старику принёс."},{"kind":"paragraph","text":"Без ног дедуля наш был, на кровати всё время, в тишине и одиночестве. Баба целыми днями хозяйством пернатым и цветами занималась, к деду редко заглядывала. Батька к старику и вовсе неделями не показывался — смрада старческого на дух не переносил. Я в основном и заходил."},{"kind":"paragraph","text":"А комнату дед самую малую в доме занимал. Две кровати в ней стояли — родные сёстры первым бронепоездам. На той, что у стенки, хлам кучами свален был: одежда, подушки, прочее — остатки той самой зажиточности, о которой бабуля всё время вздыхала. А уж на той, что у окна, сам дедуля обосновался. Лежал, днями фотоальбомы пересматривал, из рук своих серебряных выпустить боялся. Смирился с жизнью, которая одними воспоминаниями осталась. По молодости всю страну вдоль и поперёк исколесил по долгу службы. В какой стороне света ни фотографировался — везде ноги были. А домой вернулся — не стало ног! В лесхозе потерял, по травме производственной. Но инвалидом себя не считал. Как был в душе моряком, так им и остался."},{"kind":"paragraph","text":"— Дед, а баба меня со двора не пускает! — пожаловался я."},{"kind":"paragraph","text":"— И правильно делает! — дед ответил. — Зазеваешься — под машину попадёшь, без ног останешься. Или в реку, чего доброго, свалишься! А утопшему и от ног толку нет."},{"kind":"paragraph","text":"— Так я к реке и не думал, — соврал я. — В фотоателье сходить хотел."},{"kind":"paragraph","text":"— В фотоателье? — удивился дедуля."},{"kind":"paragraph","text":"— Ну да. У тебя целые альбомы фотографий, а у меня ни одной! Обидно."},{"kind":"paragraph","text":"Дед задумался на минуту, в окно приоткрытое, через занавеску, бабе крикнул:"},{"kind":"paragraph","text":"— Галя! Галя! Малого со двора пусти!"},{"kind":"paragraph","text":"— Это ещё зачем? — баба отозвалась."},{"kind":"paragraph","text":"— В ателье пусть сходит, сфотографируется, пока ноги есть!"},{"kind":"paragraph","text":"— Ещё чего выдумал! Дома пусть сидит!"},{"kind":"paragraph","text":"Я к деду на кровать присел, одеяло ему поправил, вздохнул горестно."},{"kind":"paragraph","text":"— Вот так, — голосом печальным произнёс. — Вроде и ног полно, а идти этими ногами некуда!"},{"kind":"paragraph","text":"Улыбнулся дедуля ласково, рукой по шевелюре моей провёл."},{"kind":"paragraph","text":"— Слышь, ты сопли вытри! Моряки не плачут! Давай прямо через окно, в сад! Там — через забор. Я тебе разрешаю. Чуть что, скажу — отпустил!"},{"kind":"paragraph","text":"— Ох и вкатит тебе бабуля за разрешения подобные!"},{"kind":"paragraph","text":"— И что она мне сделает? — засмеялся дед. — Ноги, что ли, оторвёт? Только это, к реке — ни шагу!"},{"kind":"paragraph","text":"— Ясное дело! — подмигнул я дедуле, на подоконник взбираясь."},{"kind":"paragraph","text":"Ясное дело, к реке сразу и направился."},{"kind":"paragraph","text":"А река Явь прямо через наш посёлок протекала. Большая, красивая, неухоженная. Коварной считалась в русле своём — тонули в ней многие. Но я всегда понимал, что реку в этом глупо упрекать. Люди любят на душу бессмертную полагаться, а чаще на смертное тело следовало бы. Ну а река — она течёт себе и течёт. Её дело именно в этом течении, а не в судьбах людских."},{"kind":"paragraph","text":"Вот и любил я течение это наблюдать, каждую возможность использовал. Даже место секретное у меня для этих наблюдений со временем нашлось: с моста по тропинке налево, через кусты, мимо развалин бывшего сырного комбината, к садам Юрьевским."},{"kind":"paragraph","text":"Ивы там красивые, осока, берег хороший. Явь наискось видно, прямо как на ладони. Тихо, хоть и посреди посёлка. Сядешь на берегу — и даже не верится, что вокруг избы, судьбы, самогон, почтальон тётя Люба на велосипеде, два дома сгоревших, четверг на календаре, клуб в аварийном состоянии, автобаза, цистерны, два кладбища, старое и новое, но мамы ни на одном нет, потому что в городе похоронили."},{"kind":"paragraph","text":"А на Явь глянешь — сразу спокойнее становится. Как будто лет двадцать поверх своего возраста прожил, и всё, что случилось в жизни плохого, произошло когда-то давным-давно. Так давно, что и сожалеть об этом глупо и незачем."},{"kind":"paragraph","text":"Вот туда и направился."},{"kind":"paragraph","text":"Одно смутило — фигуру заметил. Как раз на моём месте сидела."},{"kind":"paragraph","text":"Девица. Юная совсем. Платье простое, в клеточку."},{"kind":"paragraph","text":"Присмотрелся внимательнее — глазам не поверил. Варя из седьмого «Б». Та самая... Пару раз в школе взглядами встречались — оторваться от глаз её не мог. В них — та же Явь, но такая, в которой захлебнуться не страшно, потому что только с этого настоящая жизнь и начинается."},{"kind":"paragraph","text":"А вот ближе познакомиться с Варей у меня не получалось. В школе она редко появлялась на правах ребёнка из семьи неблагополучной. Пропадала часто, с милицией её искали. Каждый раз находили, но где-нибудь не в посёлке нашем. Говорили, что садилась Варя на электричку и ехала, куда рельсы ведут. Возвращали потом её, головами кивали, родителям на вид ставили. Но Калугиных вся округа и без того знала. Им что на вид ни поставь — всё выпьют."},{"kind":"paragraph","text":"А сама Варя — красивая, скромная, грустная. Веснушки, как Млечный Путь. Целая вселенная."},{"kind":"paragraph","text":"Откашлялся я громче, чтобы обозначить своё присутствие и Варю не испугать. Она оглянулась, щёки ладонями вытерла. Видно, что плакала недавно, но вряд ли топиться пришла. Иначе уж утопилась бы давно."},{"kind":"paragraph","text":"— Ой! — сказала. — А как это ты сюда забрёл? Тут ведь обычно человека не встретишь!"},{"kind":"paragraph","text":"— Почему это? Я здесь часто бываю."},{"kind":"paragraph","text":"— И чего?"},{"kind":"paragraph","text":"— А просто так. Место моё здесь секретное."},{"kind":"paragraph","text":"— Секретное?"},{"kind":"paragraph","text":"— Ну да. Когда заебёт всё на свете, сюда прихожу отдыхать душой и мыслями."},{"kind":"paragraph","text":"Неловко, конечно, в нежностях таких признаваться. Не по годам сантименты. Но и врать Варе не хотелось. Почему-то совсем не хотелось."},{"kind":"paragraph","text":"— Вот и я из дому убежала, — вздохнула Варя."},{"kind":"paragraph","text":"— А чего убежала? — поинтересовался я."},{"kind":"paragraph","text":"— Мать с батькой опять напились, лица друг другу разбивают, кричат. Как и всегда. А я боюсь."},{"kind":"paragraph","text":"— А чего боишься?"},{"kind":"paragraph","text":"— Так ведь орут..."},{"kind":"paragraph","text":"Беспомощно сказала, совсем как девочка маленькая. Успокоить мне Варю захотелось."},{"kind":"paragraph","text":"— Ну орут и орут. Они и дальше пить будут, буянить. Выбелятся со временем, отменятся. Умрут потом. Они уже и сейчас почти умерли. Просто сами этого пока не осознали. А мёртвых жалеть надо. Бояться-то их чего?"},{"kind":"paragraph","text":"— А я всё равно боюсь."},{"kind":"paragraph","text":"— Ну, тогда терпи, Варя. Если очень долго терпеть, со временем похуй станет!"},{"kind":"paragraph","text":"— А ты откуда знаешь? — недоверчиво на меня глянула."},{"kind":"paragraph","text":"— Ну а как не знать? У самого батька по бабам шатается. Они его, дурака, для виду расцелуют, напоят, деньги заберут, а самого под забором или в канаве бросят. Мать своими похождениями со света изжил. Тут уж выбора не остаётся: или в Явь, или похуй."},{"kind":"paragraph","text":"Задумалась Варя."},{"kind":"paragraph","text":"— Не хочется. По-другому хочется, — тихо сказала."},{"kind":"paragraph","text":"— А как это — по-другому?"},{"kind":"paragraph","text":"— Ну, чтобы и не в Явь, и не похуй."},{"kind":"paragraph","text":"— Вроде любви, что ли? — догадался я."},{"kind":"paragraph","text":"— Ну да."},{"kind":"paragraph","text":"Помолчали потом. Долго помолчали. После слов о любви всегда почему-то молчать хочется."},{"kind":"paragraph","text":"А потом снова разговаривали. Много разговаривали, до самого вечера."},{"kind":"paragraph","text":"Я Варе рассказал, что мы раньше в городе, в общежитии жили. Но папа маму вроде бы вообще никогда не любил и женился на ней только потому, что я родился. А у мамы родных не было, и бабуля маму поэтому терпеть не могла, ведь семья бабули всегда считалась зажиточной и уважаемой. Ещё вспомнил, как однажды в детстве по неосторожности папе на брюки тарелку горячего борща опрокинул. Он потом долго скакал по комнате и кричал маме: «Зачем ты его родила? Зачем ты его родила?»"},{"kind":"paragraph","text":"Варя рассказала, что живут они здесь давно, сколько она себя помнит. Хотя в молодости отец всё по заработкам мотался, денег много заработать планировал, чтобы в столицу переехать и жить не хуже, чем другие люди. Но у него не получилось, потому что работать тяжело он, на самом деле, очень не любил, а вот водку пить ему всегда хорошо удавалось. А мама очень хорошей была, но только раньше. Намного раньше — ещё когда сама Варя совсем маленькой была. Такой маленькой, что даже ноги колесом. Вот именно тогда какой-то дядя Георгий предлагал маме всё бросить и с ним уехать. Куда-то далеко уехать. Так далеко, что самолётом лететь и потом ещё несколько дней добираться. И Варю с собой забрать хотел. Но мать в самый последний момент почему-то передумала. Вроде как честь свою терять не захотела, потому что люди языками чесать начнут и мало ли что ещё. Дядя Георгий долго ждал, надеялся, что мама передумает. Но мама не передумала. Поэтому дядя Георгий в конце концов уехал, а мама сразу после этого запила. Потому что ошиблась, наверное, и надо было с дядей Георгием уезжать. Вот так и получилось: когда папа пьёт и денег не зарабатывает, а мама пьёт и о своей ошибке всё время думает — тогда плохо в семье. Тогда громко и мордобой. А сама Варя много раз сюда приходила топиться, но не утопилась, потому что захлёбываться очень страшно и жить почему-то всё равно хочется. Но только не здесь, а где-нибудь там. Поэтому и садилась иногда Варя на электричку, ехала в любую сторону, лишь бы убежать, скрыться, вырваться. Но потом понимала, что ни на шаг не уехала, а осталось там, где была. Навсегда осталась."},{"kind":"paragraph","text":"— Это потому, что убегаешь ты неправильно, — честно сказал я Варе."},{"kind":"paragraph","text":"— Как это — неправильно?"},{"kind":"paragraph","text":"— Ты в направлениях убегаешь. А в направлениях везде всё одинаково. Убежать только в будущее можно."},{"kind":"paragraph","text":"— В будущее? — удивилась Варя."},{"kind":"paragraph","text":"— Конечно. На то оно и будущее. В нём у каждого шанс есть. Главное — не просрать его, шанс этот."},{"kind":"paragraph","text":"Снова задумалась Варя, на Явь взгляд перевела."},{"kind":"paragraph","text":"— А что там, в этом будущем? То же самое, что и в направлениях. Только ещё и одной."},{"kind":"paragraph","text":"— Так в будущее поодиночке соваться нечего. Только с кем-нибудь."},{"kind":"paragraph","text":"— А с кем же?"},{"kind":"paragraph","text":"— Ну, не знаю. С кем-нибудь, кому тоже в будущее охота."},{"kind":"paragraph","text":"— Вроде тебя, что ли? — улыбнулась Варя."},{"kind":"paragraph","text":"Но улыбнулась хорошо, без насмешки. Щёки мои напрасно вспыхнули."},{"kind":"paragraph","text":"— Ну это я так, к слову, — попытался оправдаться я. Но оправданий не потребовалось."},{"kind":"paragraph","text":"— А я бы и с тобой не против, только если в этом будущем всё хорошо будет. Даром ли здесь, в нашем месте, встретились? Одинаково на Явь смотрим."},{"kind":"paragraph","text":"За руку я в этот момент Варю взял. Не так, чтобы уж прямо с намёком, а так, чтобы действительно вместе получилось. И оно начало получаться. Руку Варя не убрала."},{"kind":"paragraph","text":"— А когда это будущее, по-твоему, начнётся? — поинтересовалась."},{"kind":"paragraph","text":"— Скоро, Варя, скоро уже. Школу окончим. Сами за себя решать станем. С этого будущее и начинается. Главное — не бояться его."},{"kind":"paragraph","text":"— И что мы сразу в будущем делать будем? В город уедем?"},{"kind":"paragraph","text":"— Обязательно. Квартирку там найдём, работу. И не так, чтобы для заработков и ради столиц, а просто для себя, для каждого следующего дня. По хозяйству я, конечно, не особо хваток. Даже плинтус не знаю, как правильно прибивать, если ремонт вдруг делать придётся. А в будущем ремонты всегда случаются. Но я буду стараться, обязательно что-нибудь придумаю. Вот увидишь!"},{"kind":"paragraph","text":"— И у нас всё будет хорошо?"},{"kind":"paragraph","text":"— Конечно. Главное, чтобы вместе. Будущее только на этом и основывается."},{"kind":"paragraph","text":"Поднялись мы в этот момент с земли. Вечерело. Я Варе свитер свой на плечи накинул, чтобы теплее ей было. Она на меня взглянула с благодарностью. Так что и мне теплее стало. Долго стояли потом в тишине, смотрели, как камыш нежно колышется, как вода берег целует, как небо плотнее к земле прижимается."},{"kind":"paragraph","text":"— А я пить не буду. Обязательно не буду. Ради нашего будущего, — вдруг прошептала Варя."},{"kind":"paragraph","text":"— А я на сторону ходить не стану. Вот прямо ни разу. Ни единого!"},{"kind":"paragraph","text":"— Смотри! Если пойдёшь — яйца оторву! — тихо сказала Варя и сильнее сжала мою руку."},{"kind":"paragraph","text":"А потом мы снова смотрели на Явь."},{"kind":"paragraph","text":"Садилось солнце, отражалось в воде."},{"kind":"paragraph","text":"Было очень красиво."}]'::jsonb,
  '2023-12-31T12:00:00.000Z'
)
