  published_at = EXCLUDED.published_at;

INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd4-mat',
  'Мать',
  (SELECT id FROM "Authors" WHERE name = 'Тумен Монгуш' ORDER BY id LIMIT 1),
  'mrd4/mrd4-mat.jpg',
  'data:image/jpeg;base64,',
  1586,
  915,
  'Посвящается Нурзат',
  '[{"kind":"image","path":"mrd4/mrd4-mat.jpg","caption":null},{"kind":"paragraph","text":"Посвящается Нурзат"},{"kind":"paragraph","text":"Моя мать умерла год назад, и весь этот год, каждый день, я думал, как выглядит её тело. Там уже кости? Или же есть что-то, что напоминает старую кожу, туго обтягивающую череп, грудную клетку и всё остальное тело? Я бы мог обратиться к медицинским книгам или же к интернету, чтобы узнать, как разлагается живая плоть, но даже сама мысль об этом вызывала во мне отвращение к себе, стыд за то, что после её смерти, после её жизни, в которой я принимал участие с самого рождения, меня волнует лишь её состояние в гробу, под землёй, тем более зимой. Я пытаюсь вспомнить что-то другое о ней, но тогда всё, что мне приходит в голову, — это похороны. Она лежала в шестиугольной вытянутой коробке с лакированными стенками, руки скрещены на груди, а на лице не осталось ни одной сокращённой мышцы, которая бы говорила о её последней эмоции, о мыслях перед смертью — ничего, только маска, надетая рукой небытия. При этом меня и не волновало, что ни одного воспоминания мне не приходило в голову, волновал лишь гроб, лежащий в земле, и все биологические и химические особенности человеческого тела после смерти, и не волновало, что однажды и я окажусь там. Не думаю, что это нечто, что стоит познавать. С детства нас учат познавать только самое прекрасное: нас водят в парки, делают подарки на Новый год или дни рождения, радуются каждой нашей пятёрке в школе, но никогда не показывают то, с чем придётся столкнуться каждому. Нас учат, что жизнь надо любить и любить надо людей, и везде искать любовь. Но как найти любовь в мёртвом теле, в одиночестве?"},{"kind":"paragraph","text":"Воспоминания о ней ко мне приходили постепенно, что заставляло меня чувствовать вину, словно я сам приложил руку к её смерти, к её старению, к её болезни, словно я ступил на тропу, ведущую меня к причине этой смерти, и причиной этого являлся я. Первое воспоминание было связано с зимним утром, когда я проснулся в холодной комнате и не хотел выбираться из-под одеяла, как это бывало в детстве перед детским садом; тогда мать сажала меня на колени и прижимала к себе так сильно, что пропадал холод и я чувствовал запахи её одежды и волос. Не нужно было гладить по голове, спине, говорить ласковые слова: достаточно только обнимать меня — и тогда я пойму, что она любит меня. Когда это воспоминание всплыло передо мной, я удивился, как удивляется человек, впервые увидевший закат. Наверное, я просто не понимал, что нужно чувствовать в такие моменты. Нужно ли заплакать? Найти в себе тоску?"},{"kind":"paragraph","text":"К тому моменту я работал в небольшом кафе поваром и познакомился с женщиной по имени Нурзат. Она работала там уже семь лет. Она была доброй. Она встречала меня с улыбкой, ведь каждый из нас напоминал себе, что в этом мире всегда есть тот, кто поймёт наши тоску и страдания. Каждый вечер после работы за ней приходила её дочь, ученица одиннадцатого класса, и каждый раз в момент их встречи я желал увидеть улыбку на лице Нурзат — улыбку, с которой начинается её настоящая жизнь, её истинное «я», которое будет воплощаться и в дочери. И почему дочь приходила к ней каждый вечер? Потому что любила. Для меня это высшее проявление любви: матери не приходилось ехать в автобусе в одиночку, как это бывало со многими женщинами, которых я встречал по дороге домой; они смотрели в окно, где уже темно, холодно и одиноко. О чём они думали в тот момент? Наверное, ни о чём. Потому что об одиночестве не думают. Им живут. А вот Нурзат слушала, как прошёл день её дочери в школе, и то улыбалась, то расстраивалась, то рассказывала, какие посетители приходили в кафе; глаза Нурзат становились шире, когда её наполняли эмоции, а порой грустили, когда она не могла понять, как могут люди быть такими несчастными. А что потом? Они приедут домой, снимут верхнюю одежду, вместе приготовят ужин, а затем лягут спать. Да, вот это жизнь. Вот это любовь."},{"kind":"paragraph","text":"Моя мать никогда не готовила мне ужина. Она работала ночами, только утром мне делала завтрак, отвозила в школу, а по возвращении занималась тем, чего я никогда не замечал: мыла полы, ванную, туалет, посуду, стирала руками одежду, чистила мою обувь, гладила школьную форму, покупала продукты и несла огромные мешки на четвёртый этаж, затем ложилась спать, просыпалась и уходила на работу, когда я возвращался в уголок земли, готовый для жизни. И при этом я никогда не чувствовал себя одиноко: всё вокруг меня напоминало мне о её любви."},{"kind":"paragraph","text":"Мы жили в двухкомнатной квартире, я спал в одной комнате, а мать — в гостиной, где я каждый вечер ей готовил постель, то есть расстилал диван, стелил простыню, укрывал одеялом, при этом распахнув его в воздухе и нежно уложив, как лёгкую скатерть на стол, надеясь, что она когда-нибудь увидит, как искусно я это делаю; и часто представлял, как она ложится, положив руки под подушку, укрывшись одеялом до самой головы, закрывает глаза и засыпает в тишине комнаты. Однажды я вернулся из школы раньше, чем она ушла на работу, вошёл в гостиную очень тихо, зная, что она ещё спит; и вот она лежит, мир замер, свет вечернего солнца застыл на стене, и лишь ветви деревьев качаются за окном. В такие моменты я чувствовал, что о ком-то забочусь, что чья-то жизнь зависит и от моего существования. Я её любил."},{"kind":"paragraph","text":"Только тогда я стал понимать всю странность и нерациональность природы воспоминаний. Воспоминания — совершенно другая жизнь, никогда не знаешь, что попадётся тебе в следующий раз: то, что заставит тебя улыбнуться или заплакать. И прошлое каскадом обрушивалось на меня, и я не знал, что с ним делать, и не понимал, зачем оно вообще приходит в мою жизнь. Описать эти воспоминания в дневнике? Рассказать кому-то? А что дальше? В животном мире память используется для выслеживания жертвы, для возвращения в стаю, для обучения охоте, но какой смысл держать в голове воспоминания, которые приносят одну лишь боль, смотреть на полное радости или печали время, которое уже никогда не вернуть? И я пытался найти в них путь к истинной сущности моей матери, найти место её реального объективного существования в мире, где её уже, по сути, нет."},{"kind":"paragraph","text":"Вспомнил… Она ведь тоже потеряла свою мать. Мне тогда было двенадцать лет. Бабушку я не особо помню — приезжал к ней крайне редко из-за матери, которая и сама-то особо не поддерживала с ней связи, и их нить, обычно протягивающаяся между матерью и дочерью, была готова вот-вот оборваться, как мне казалось. Но когда бабушка умерла — а я сидел в это время в своей комнате, — по всему дому раздался пронзительный крик матери, словно кто-то ударил её ножом. А затем… снова похороны. Мать не плакала. И только сейчас я задаюсь вопросом: почему? Потому ли, что всё-таки взяло верх её безразличие к судьбе, и прошлому, и будущему, которое могло быть у них обеих, или же она смирилась с тем, что рано или поздно мы остаёмся одни?"},{"kind":"paragraph","text":"В каждый день рождения бабушки, в октябре, когда листья уже опадают на сырую землю, и жёлтые, красные деревья становятся как никогда близко к вечернему пламени солнца, и эта гамма бликами танцует перед глазами, мать посещала кладбище, где была похоронена бабушка, убирала листья, протирала её памятник и клала гвоздики, затем вставала перед мрамором, на котором выгравировано лицо её матери, и молчала. И вновь… воспоминания. Я называл этот день днём молчания. В этот день мать ничего не говорила мне. Я никогда не понимал, зачем она берёт меня с собой, тем более что мне было больно находиться в этот день рядом с ней, я чувствовал себя ненужным, я даже ревновал мать к бабушке, что её любовь к умершему человеку настолько сильнее любви ко мне, что она предпочтёт сделать вид, будто меня не существует. Не скажу, что теперь я понимаю свою мать. Думаю, я никогда не смогу её понять. Но я представляю, что матери было ужасно одиноко в этот день, что ей было страшно в одиночку вновь увидеть лицо своей матери на памятнике, что если бы она пришла туда без меня, то вообразила бы себе, что она никому не нужна, что её никто не любит и не полюбит так, как любила её бабушка; и тогда у меня ком становится в горле. И я начинаю понимать, почему она всегда молчала в тот день: если бы я или она сказали бы хоть слово, то она бы разразилась слезами. Её слёзы, наряду с её беспомощным криком, — самое страшное, что я когда-либо видел и слышал в своей жизни. Она плакала и кричала, когда её избивал отец, и ей приходилось со слезами вести меня в детский сад. В детский сад ведь идут не думать о жизни, так? Туда идут удовлетворять детское любопытство, набираться знаний о счастье и радости, но путь мой в это царство грёз лежит через тернии страданий, слёз и криков. Слёзы матери — это доказательство того, что нас никогда не ожидает то, чего мы ждём. Жизнь подаёт нам то… ну, то, что подаёт, и либо ты принимаешь, либо заканчиваешь жизнь самоубийством. Я выбрал первое только потому, что мне было интересно, какое воспоминание готово выступить передо мной следующим."},{"kind":"paragraph","text":"Квартира нам досталась после смерти бабушки, и, насколько я помню, за двадцать лет там ничего не поменялось, и до сих пор остаётся прежним, каким было в детстве, отрочестве и юности не только моих, но и моей матери; и квартира эта не хранила в себе ни толики жизни, которая когда-то господствовала в нашей стране, словно она была отделена от пространства и затеряна во времени. В особенности во времени, когда была жива моя мать. Что из всего этого принадлежало ей? Что из всей этой квартиры она любила, никому не рассказывая об этом? Где она хранила секреты? Но у неё не было никаких секретов, было только то, о чём не хватало сил рассказать, о чём больно было вспоминать и думать; она только хранила в себе всё и надеялась, что это гадкое, тёмное и мрачное останется в глубине её души и никогда оттуда не выберется, чтобы испортить ей жизнь, которую она пыталась наладить. И у неё получалось налаживать нашу жизнь, только не хватило времени."},{"kind":"paragraph","text":"Среди старых фотографий я нашёл видеозаписи, которые мама иногда снимала, когда я был маленьким. На них она была ещё молода, а самое главное, счастлива. На них она всегда улыбалась и любила."},{"kind":"paragraph","text":"«Так. Сегодня шестое июня. Мы купили видеокамеру. И... мы поехали на пляж. У моего сына день рождения, мы приехали к озеру. Мы здесь часто бываем летом. Вот он там стоит. Ванечка! Помаши рукой на камеру! Только не плавай далеко, хорошо?»"},{"kind":"paragraph","text":"«Сегодня ясная такая погода. Вода тёплая. И народу так много. Но всё равно хороший день. Сейчас мы поедем в пиццерию. Почему бы и нет, в его день рождения-то»."},{"kind":"paragraph","text":"«Вот. Я буду снимать всё, что с нами произойдёт сегодня. Просто мне не хочется забывать этот день. Я его так ждала»."},{"kind":"paragraph","text":"«Иди ко мне, давай снимем себя. Садись. Меня зовут Мария, и мне двадцать семь лет. А это мой сын, Ваня, и ему… сколько тебе, ну-ка скажи. Правильно, пять лет. Ты моя умничка»."},{"kind":"paragraph","text":"«Мы только что приехали в пиццерию, и я сказала ему сходить помыть руки, а сама дала официантке тортик. Они там зажгут свечки, всё такое, вынесут. Надеюсь, ему понравится. Так, надо кассету проверить, а то ещё закончится, когда не надо»."},{"kind":"paragraph","text":"«Вот мы взяли очень большую пиццу. Тут всякие овощи, колбаски, ещё сыр такой вязкий, да? Как тебе, нравится? Вообще вкусная, да? Может ещё возьмём? Не хочешь? Объелся? Иди ко мне, мой мальчик! Дай я тебя поцелую! Ты мой хорошенький!»"},{"kind":"paragraph","text":"«Ой, смотри, нам что-то несут! Смотри-смотри! Тортик, смотри! Ура, тортик! С днём рождения! С днём рождения! С днём рождения! Давай, задувай свечки! Ещё-ещё немного. Ну давай тогда со второго раза, ничего страшного. Ура-а-а! С днём рождения тебя, моё солнышко!»"},{"kind":"paragraph","text":"«Итак, сегодня шестое июня, у моего сына день рождения, и... и я тебя очень люблю. Да? Ты же знаешь, что я тебя люблю? Я тебя так сильно люблю. А маму ты любишь? Сильно любишь? Даже сильнее, чем я тебя? Дай я тебя поцелую. Я так сильно тебя люблю»."},{"kind":"paragraph","text":"«Смотрите, он уснул, прямо в автобусе. Вечер уже всё-таки. Устал, наверное. Он такой красивый у меня. А за окном огни красивые. Жаль, что он их не видит. И... если ты увидишь эту запись спустя долгое время, я хочу, чтобы ты знал, как я тебя люблю. И я так счастлива, что встретила тебя. Я думаю, что если бы я не любила тебя, то никогда бы не родилась. И я счастлива, что сейчас ты рядом со мной. И я думаю, что ты всегда будешь рядом со мной. И я буду с тобой, ведь я… люблю тебя. Я тебя очень люблю, и мне так страшно, что мне придётся расстаться с этой жизнью, с тобой»."},{"kind":"paragraph","text":"«Вот мы и дома. Он еле дошёл. Я думала, что смогу дотащить его, но он уже слишком тяжёлый. Я уже не могу даже, как раньше утром, посадить на колени и обнять его. Мне всегда так нравилось это делать»."},{"kind":"paragraph","text":"«Я только что посмотрела всё, что сняла за день, и мне стало так грустно. Я, видимо, была так заворожена этим днём, что всё забыла, и только вспомнила через записи; и грустно, что даже такие счастливые воспоминания однажды забудутся. Но я всегда буду любить своего сына, и я думаю, это намного важнее воспоминаний»."},{"kind":"paragraph","text":"«Вот он спит. Ещё маленький он всё-таки. Ну-ка, ложись вот так, удобнее будет. Спокойной ночи, мой хороший»."},{"kind":"paragraph","text":"«Я так много всего вспомнила. Как он только начал ползать, ходить. Прямо, знаете, будто я видела всю жизнь, как вообще она зарождается. Ой, не знаю, сложно всё это. Наверное, я тоже сильно устала, ха-ха. Что ж, я думаю, на этом всё. Это был прекрасный день. И я думаю, таких дней будет ещё много. И надеюсь, я смогу их заснять или хотя бы запомнить. Боже, не могу, слёзы наворачиваются. Если ты однажды это увидишь, я хочу, чтобы ты знал, как люблю тебя. Я так хочу увидеть тебя взрослым. Ну всё, пока-пока. Всех люблю. Всем спокойной ночи. Чмок»."},{"kind":"paragraph","text":"В них она пыталась отразить и сохранить свою жизнь, но раз уж она перестала снимать, то скорее всего, что-то пошло не так; возможно, она поняла, что… возможно, она поняла… Простите, я сбился с мысли. Возможно, она поняла, что одних только кадров, фотографий и записей на бумаге недостаточно, чтобы оставить в этом мире часть себя. Всё материальное однажды исчезнет. И мы однажды исчезнем. И никто не узнает, кем мы были на самом деле. А может быть, и неважно, кто мы такие? По крайней мере, для людей, которые любят нас."},{"kind":"paragraph","text":"Мама, где же ты?.."},{"kind":"paragraph","text":"— Ну что, идём? — спросила меня Нурзат."},{"kind":"paragraph","text":"Моя смена закончилась одновременно с её, и Нурзат предложила мне прогуляться с ней и её дочерью в ближайшем парке. Это было их ежегодной традицией — встречать осень со всей её желтеющей листвой и ласковым ветром в тихом парке, идти по дорожке, которая, как кажется, никогда не закончится; и вот я стал участником их прогулки. Мы дошли до самой гущи парка, где казалось, что уже находишься в глубине леса; сели на деревянные скамейки со столиком, Нурзат налила в стаканы горячего чаю, угостила меня, и тогда наступила тишина. Да, точно, как в те дни. И я так же боялся что-то сказать."},{"kind":"paragraph","text":"Подул ветер, и тогда во мне уже не просыпались забытые воспоминания, а в меня начала просачиваться жизнь, которая вот уже миллионы лет не прекращается, жизнь, приведшая меня в этот парк, та жизнь, что приводила мою мать к могиле бабушки, и жизни каждого, кто мне был дорог, стали так материальны и ясны передо мной, что уже ни одно воспоминание не имело никакого смысла. Воспоминание — это письма, которые никогда не дойдут до адресата, и в этом нет трагедии, потому что достаточно того, что нечто побудило тебя написать эти письма. Я не стал думать, что переживала Нурзат, когда она потеряла свою мать, не стал думать, что будет переживать её дочь после её смерти: я отчётливо видел, как само присутствие Нурзат в жизни дочери отражается и растёт в душе девочки. Нет ни прошлого, ни будущего: есть я."},{"kind":"paragraph","text":"Мы говорили, мы смеялись, мы жили. Затем настало время прощаться, я смотрел, как они становятся всё дальше и дальше от меня. Но я чувствовал их присутствие в своей душе, чувствовал, что во мне есть что-то, что составляет меня. И этого достаточно. Идти вперёд, даже если путь ведёт в никуда."}]'::jsonb,
  '2023-12-31T12:00:00.000Z'
)
