INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd4-raspisanie-pogromov-ili-siniy-dym-kitaya-ili-nash-chelovek-v-gavane',
  'Расписание погромов, или Синий дым Китая, или Наш человек в Гаване',
  (SELECT id FROM "Authors" WHERE name = 'Эдуард Диа Диникин' ORDER BY id LIMIT 1),
  'mrd4/mrd4-raspisanie-pogromov-ili-siniy-dym-kitaya-ili-nash-chelovek-v-gavane.jpg',
  'data:image/jpeg;base64,',
  1586,
  892,
  'Пасмурным московским утром первого декабря 2017 года я подошёл к парочке, выпивающей водку на Сретенке. Это были мужчина и женщина. Таких принято называть бомжами. Не факт, что они действительно не имели своего дома, но,',
  '[{"kind":"image","path":"mrd4/mrd4-raspisanie-pogromov-ili-siniy-dym-kitaya-ili-nash-chelovek-v-gavane.jpg","caption":null},{"kind":"paragraph","text":"Пасмурным московским утром первого декабря 2017 года я подошёл к парочке, выпивающей водку на Сретенке. Это были мужчина и женщина. Таких принято называть бомжами. Не факт, что они действительно не имели своего дома, но, с другой стороны, пить водку рано утром, разложив на целлофановом пакете, лежащем на краю скамейки, порезанную дешёвую колбасу и маринованные огурцы, будут только маргиналы или аристократы духа."},{"kind":"paragraph","text":"Вот к последним я, несомненно, и принадлежал. Но, несмотря на известное утверждение «и последние станут первыми», не испытывал желания стать маргиналом. Всё, край. Пусть и относительный."},{"kind":"paragraph","text":"— Ребята, здравствуйте, у вас есть нож или ножницы? — спросил я."},{"kind":"paragraph","text":"— Есть, — с некоторой долей любопытства ответил мужчина и протянул нож, которым, возможно, до этого открывал бутылку и резал колбасу, маринованные огурцы и хлеб. А день назад, возможно, собутыльника. Я подумал об этом, увидев на его пальцах светло-синие тюремные наколки. Назвать их голубыми было никак нельзя, глядя в эти ещё не выцветшие синие глаза."},{"kind":"paragraph","text":"— Благодарю, — сказал я."},{"kind":"paragraph","text":"Не стал добавлять «от души». Не до этого уж."},{"kind":"paragraph","text":"Оттянул марлю под подбородком и разрезал повязку. После чего снял с головы бинты, которые мне наложили часов десять назад."},{"kind":"paragraph","text":"«Правильно, что снял», — думал я через полчаса, заряжаясь водкой на улице. Я купил бутылку благодаря рекомендации, данной мне бомжами. До одиннадцати водку официально не продают, как известно, но если у тебя есть хорошие связи в обществе, пусть и на его дне, то ты не пропадёшь."},{"kind":"paragraph","text":"Я прошёл немного в сторону станции метро «Чистые Пруды». Сел на скамейку, подложив под себя кусок картона, который взял в магазине, и выпил прямо из горла, закусив мясной нарезкой. И только тогда понял, что водку в Москве продают с восьми утра. Так что рекомендация купить её в угловом магазине была просто дружеским советом."},{"kind":"paragraph","text":"Водку я пил и вчера вечером, но под камерой. Это было самое большое отличие. Были и другие. Я сидел за столом, кроме нарезки были соленья, бутылок было три, и мне составлял компанию рок-идол девяностых — Сергей «Паук» Троицкий."},{"kind":"paragraph","text":"Собственно, мы все — я, журналистка Тамара, оператор Виктор и пресс-секретарь Паука Светлана — находились у него дома под Мытищами. Снимался сюжет для программы «Водка против коньяка». Меня специально вызвали для этих съёмок из Питера, оплатив «Сапсан» оттуда и «Невский экспресс» туда."},{"kind":"paragraph","text":"После того, как Тамара и оператор уехали, мы с Пауком продолжили интересную и захватывающую дискуссию, в результате которой оба попали в больницу. Он в больнице остался, я — нет."},{"kind":"paragraph","text":"Ночью я уехал в Москву. О съёмках, а также о приглашении на концерт в субботу на фестиваль «Железный марш» теперь можно было забыть. Но это не страшно — по крайней мере, я остался жив после удара саблей по голове. Самого момента удара я не видел, так как сидел спиной, но ангел в виде Светланы отвёл руку тёмных сил, сделав его касательным. И вот я сижу сейчас на Сретенке на скамейке, пью водку, закуриваю и начинаю думать: что делать дальше?"},{"kind":"paragraph","text":"К моей скамейке приближалась ненормальная женщина. То, что она была ненормальной, было понятно по тому, как она вела на поводке кошку. Такое я видел только однажды. Двадцать лет назад в подмосковном Красногорске. Я жил в коммунальной квартире рядом со стадионом «Зоркий». Все её обитатели были кошатниками. Причём вполне разбирающимися в особенностях кошачьей жизни. Кроме одной старушки, довольно вредной и злобной. И эта старушка решила не отставать от других двуногих обитателей квартиры и завести себе кошку. Потом ещё одну. И ещё. Вот именно их, несчастных и всегда молчащих, она и выгуливала на поводках. Странно, что без намордников."},{"kind":"paragraph","text":"И вот ещё одна безумная женщина. Она подошла к скамейке, кивнула мне и села, взяв кошку на руки."},{"kind":"paragraph","text":"На улице было относительно прохладно. На кошке был комбинезон. Женщина — на вид ей было лет шестьдесят — посмотрела на меня и сказала:"},{"kind":"paragraph","text":"— Позавчера водила своего кота к астрологу. Теперь вот выгуливаю. Ему надо подышать воздухом теперь."},{"kind":"paragraph","text":"— Что же ему астролог такого напророчил, что ему подышать надо воздухом? Перед чем? — спросил я."},{"kind":"paragraph","text":"— Нет, не к астрологу, — рассмеялась она. — К кастрологу. Вы второй такой не понимаете. Я его кастрировала. Он ещё молодой, просто выглядит взрослым. Теперь и мне легче, и ему."},{"kind":"paragraph","text":"— Почему легче?"},{"kind":"paragraph","text":"— У вас нет кота?"},{"kind":"paragraph","text":"— Нет."},{"kind":"paragraph","text":"— Это очень плохо, что нет, — сказала она."},{"kind":"paragraph","text":"Женщина ещё немного посидела и ушла. Забавно я ослышался. Бывало, конечно, забавнее, если так можно сказать. Но однозначно с более тяжкими последствиями."},{"kind":"paragraph","text":"Я сделал глоток водки и вспомнил случай, который произошёл осенью 1989 года в войсковой части, где я служил. Случай, когда недопонимание привело к непредсказуемым последствиям."},{"kind":"paragraph","text":"Один военнослужащий увольнялся. Был он не на самом хорошем счету у командиров, поэтому уходил в числе последних, в декабре. Мало того, уходил он не из той роты, где начинал службу и прослужил почти два года, а с верхнего батальона, куда его отправили за систематические нарушения дисциплины. Как бы там ни было, время прошло и надо его уже отпускать. Он приехал в ядро части. Пока оформлялись бумаги, он зашёл в свою старую роту. Все его сослуживцы давно свалили, но был в это время в расположении роты один его приятель-земляк из призыва на полгода младше. Решили они отметить отъезд домой нашего дембеля. Причём отметить чисто символически, без алкоголя — у них и не было ничего выпить. Ничего, кроме яблочного сока в трёхлитровой банке. Как обычно, сделали штык-ножом две дырки, разлили по кружкам. Расположились в бытовке, напротив туалета. В это время зашёл в бытовку Игорь П. Когда-то наш герой его основательно гнобил. Бывало, говорил он Игорю: «Я тебя до своего дембеля сгною». Невзлюбил его, короче, за что-то. Бывает. И гнобил ведь целый год. Однопризывники Игоря уже «лимонами» стали, поднялись по армейской иерархии, а ему никак не дают почувствовать себя свободнее. А тут прошло месяца три, как дембеля отправили на верха, Игорь уж и не думал, что увидит его. Воспоминания о нём у Игоря П. были не самые хорошие. За это время он сам стал старослужащим. Дембель увидел Игоря и от радости, что домой уезжает, а к Игорю в связи с этим он уже давно никакой неприязни не чувствовал, говорит: «Попей, Игорь, сочка». «Ах ты, сука, — говорит ему Игорь в ответ, никогда ничего хорошего от него не слышавший, — сейчас ты сам, овца, с очка будешь пить»."},{"kind":"paragraph","text":"В общем, уехал дембель домой с разбитой мордой. А Игорь чуть было на кичу не уехал. И как он потом говорил, если бы он правильно понял, что́ ему предлагают, то ничего бы не случилось. Вот он, пример ошибки и недопонимания среди людей. Такой вот «аборт корабля»."},{"kind":"paragraph","text":"Бутылка была пуста наполовину. Сидеть и вспоминать былое на скамейке? Нет, как-то не хотелось. Эта женщина напомнила мне о Красногорске. Не поехать ли туда? Я не был там почти двадцать лет. А прожил в нём, в общей сумме, года два."},{"kind":"paragraph","text":"Решив ехать, я купил пластиковую бутылку с «Фантой», из которой половину вылил и налил туда водку. По крайней мере, так можно пить в метро. Все знают, что пить просто водку в метро нельзя. Тем более сейчас, при этом страшном режиме. А режим у меня был со вчерашнего вечера жёсткий — каждый час требовал очередного добавления алкоголя."},{"kind":"paragraph","text":"Правда, я немного отдохнул какое-то время назад. Идя ранним утром по улице, ещё с забинтованной головой, я спросил прохожего, молодого человека, есть ли тут какое-нибудь недорогое заведение. И объяснил ситуацию. Он сказал, что не знает, и предложил заменить злачное заведение заведением богоугодным. То есть пойти в церковь. Я не хотел идти, так как был с похмелья, но что-то мне подсказало, что такой вариант, в это ещё тёмное время суток, для меня был самым благоприятным."},{"kind":"paragraph","text":"В церкви Успения Пресвятой Богородицы в Печатниках я сел на скамейку, склонил голову и заснул. Дважды мимо меня проходили женщины. Я понимал, что они клали какие-то записки в ящик, на котором, собственно, моя голова и находилась. Мне казалось, что они кладут эти записки именно мне в голову. Точнее так подумалось в моём полусне. Было тихо и хорошо."},{"kind":"paragraph","text":"Из церкви я вышел полным сил. На улице рассвело, но оставалось пасмурно. Вот тут я и увидел бомжей."},{"kind":"paragraph","text":"Что ж, я зашёл в вагон метро. Свободных мест было много. Как и свободного времени. До «Тушинской» ехать и ехать. Я выпил «Фанты», подключил наушники к телефону и стал слушать радио. Это была радиостанция, специализирующаяся на ретро-музыке. И первой композицией, что я услышал, была ''Cause you are young'' голландской певицы Си Си Кэтч. И, конечно, я вспомнил Макса Огородова."},{"kind":"paragraph","text":"Была у меня подруга, у которой была большая грудь. Она гордилась своим бюстом не меньше, чем в прежние времена дважды Герой Советского Союза гордился своим бюстом на родине."},{"kind":"paragraph","text":"Кроме груди, действительно большой и упругой (в ранней молодости), она вполне могла похвастать одной своей историей, случившейся с ней в возрасте пятнадцати лет. Тогда она была девственницей. Вообще, лично мне в это трудно поверить, но так она говорила."},{"kind":"paragraph","text":"Как-то она была одна дома, слушала группу из свердловского города Асбест «Ариадна Оливер» (название изменено). Оля (имя тоже) обожала эту группу. Она была её фанаткой до того, как группа стала очень популярной. Подруга Оли, Катя (имя тоже), любила хеви-метал и терпеть не могла попсу. А особенно не любила популярное тогда евродиско типа «Модерн Токинг» и Си Си Кэтч. Катя не была обладательницей такого бюста, как у Оли. Собственно говоря, у неё была очень, очень маленькая грудь. Лучше сказать, что её и не было. У Кати была майка с надписью Catch. Она довольно часто ходила в ней. Как-то пришла в ней в школу. И кто-то из одноклассников, не имея ничего плохого в виду, сказал: «О, вот и наша Си Си Кэтч», показав на надпись. Катя, ненавидевшая попсу и Си Си Кэтч в частности, гневно произнесла, ткнув пальцем себе в грудь, то есть на место, где располагалась злополучная надпись: «А Си Си-то где, где Си Си-то?» И вначале не поняла, почему все захохотали. Даже Оля. И даже громче всех."},{"kind":"paragraph","text":"И Оля, и Катя любили одного мальчика. Он был их одноклассником. Звали его Виталий. Он был вежливый, сильный и смелый мальчик, просто мечта. Папа у него работал в горисполкоме."},{"kind":"paragraph","text":"Но девочки, конечно, любили его не за папу. А за него самого. Они часто говорили о нём друг с другом. Оля показала мне дневник, который она вела в те годы. Я читал и поражался тому, что она там понаписала. Чиччолина в пятнадцать, наверное, сгорела бы со стыда, прочитай она тот дневник. Если бы ей, конечно, перевели на венгерский."},{"kind":"paragraph","text":"Неизвестно, что в тот день слушала Оля, но музыка подействовала на неё своеобразно. Оля решила заняться кое-чем интимным. Надо сказать, что ей нравился не только одноклассник Виталий, но и братья Семёновы (фамилия изменена) из «Ариадны Оливер». Глеб и Вадим. Ещё ей нравились Константин Кинчев и Виктор Цой. Ещё Томас Андерс. Об этом своём увлечении она Кате не говорила. Ещё ей нравился спорадический педераст Джордж Майкл. То, что он педераст, она тогда не знала, а что такое «спорадический», ей неизвестно до сих пор."},{"kind":"paragraph","text":"Секс-шопов тогда не было, зато у Олиных родителей не было и садового участка, как у большинства соседей, поэтому огурцы они покупали в магазине. Огурцы были здоровые и зелёные. Оля спорадически, очень неглубоко, если не сказать мелко, экспериментировала с ними. Даже не мелко, а так. Она не то чтобы собиралась выйти замуж девочкой, а просто боялась неизвестного. После экспериментов Оля была заботливой и делала из этого и других огурцов и прочих овощей салат на всю семью."},{"kind":"paragraph","text":"Когда она мне рассказывала эту историю, я как раз был у неё дома и ел прекрасно приготовленное овощное рагу. Вероятно, что-то отразилось в моём взгляде, потому что Оля пояснила мне, что этим давно не занимается, у неё мужиков дофига. Я охотно ей поверил."},{"kind":"paragraph","text":"Итак, Оля ласкала себя, двигала осторожненько огурцом, занималась, короче, самообладанием. И тут ей пришла в голову мысль: встать на ноги и подойти к зеркалу, чтобы получить ещё и эффект от просмотра. Она очень любила свои груди. Очень. И вид их тряски заводил её не меньше, чем пляски — святого Вита. Она подошла к трюмо, нагнулась и стала делать то, что задумала. Всё было хорошо до того момента, пока она случайно не задела своим тазом книжный шкаф (она, кстати, была большой любительницей чтения). На шкафу стоял маленький бюст Пушкина, хотя, судя по подлости, скорее Дантеса. И этот бюстик полетел вниз. И прямо Ольге на голову. Она от неожиданности присела — и присела, конечно, на огурец. Огурец, пошляк, вошёл в неё, как говорится, по самые помидоры."},{"kind":"paragraph","text":"Ей было больно, разумеется. Огурец-то был здоровенный. Впрочем, может быть, и не очень. Но Оля говорила, что огромный. Так или иначе, Оля стала женщиной. И довольно ловко этим воспользовалась. Она вообще всегда была девушкой ловкого поведения. Рассудив, что теперь терять нечего, она соблазнила Виталия. И все девчонки в классе завидовали ей. Правда, Виталий оказался парнем не таких строгих моральных устоев, как я в его годы, и вскоре всем рассказал, чем они с Олей занимаются. Ей это не понравилось, потому что хоть в их классе и учился Виталий, сын достаточно крупного горисполкомовского чиновника, всё равно школа была полугоповской, ну а гопники есть гопники, что тут добавить?"},{"kind":"paragraph","text":"Разве то, что позже Оля поступила в училище и, как она сама с гордостью говорила, переспала со всеми своими одногопниками."},{"kind":"paragraph","text":"Судьба Виталия сложилась неожиданно. После школы он поступил учиться в пединститут на истфак. То ли само это слово «истфак», то ли что-то другое потянуло его в сторону востока. Но не в сторону фака, а в сторону мака. На востоке ведь это было всегда принято. Виталий даже из-за этого кличку получил. Его стали звать Макс Огородов. Дело в том, что на первом курсе (тогда он лишь иногда покуривал анашу) он случайно оказался в общежитии у своих одногруппников. Те куда-то собирались."},{"kind":"paragraph","text":"— Куда вы? — спросил их он."},{"kind":"paragraph","text":"— Макса Огородова пиздить, — услышал Виталий."},{"kind":"paragraph","text":"— А кто такой Макс Огородов? — удивился он."},{"kind":"paragraph","text":"— Не Макс Огородов, — пояснили друзья, — а мак с огородов пиздить."},{"kind":"paragraph","text":"И в этот день Виталий получил не только кличку, но и первый опыт «черняжки». Короче, вскоре он сторчался, и наглухо причём. Но это уже другая, наркоманская история, и меня она совсем не касается."},{"kind":"paragraph","text":"Если, конечно, не вспоминать тот случай, когда я зимой 97-го возвращался от покойного писателя Баяна Ширянова. Тогда он был жив. И даже очень. Но у него был рецидив. Он снял на день квартиру, чтобы сварить «винт», и предложил мне составить ему вечером компанию. Вероятно, это было почётное предложение, так как зависимые от наркотиков не любят делиться ими. А с его стороны подразумевалось именно это. Я отказался большей частью из-за того, что собирался ехать в клуб, где наклёвывалась реклама. Я предложил им поместить её на взаимовыгодных условиях в журнале, в котором на тот момент работал."},{"kind":"paragraph","text":"Съездил в клуб, в котором веселье только начиналось, и поехал в Красногорск, где жил. Так что скорее я возвращался не от Ширянова, а из клуба."},{"kind":"paragraph","text":"Я как-то прочитал в газете, что люди ошибаются, думая, что черепахи живут долго. Это не так. Уже общеизвестно, что черепахи живут очень мало, просто очень медленно. Вот и я подумал, что живу медленно и мало. Мало в моей жизни событий в последнее время. Мог ускориться с Баяном Ширяновым, мог ускориться в клубе. Но поехал в Красногорск."},{"kind":"paragraph","text":"Выйдя на станции Павшино, я вдруг почувствовал тоску и опустошение. Я жил в коммунальной квартире рядом со стадионом «Зоркий». Что ждёт меня там? Разговоры под бутылку с Михаилом Сарычем — малоизвестным поэтом и писателем? Или, если свернуть налево, разговоры с широко известным в узких кругах поэтом и алхимиком Олегом Фоминым-Шаховым? Или, если проехать ещё немного на электричке и выйти в городе, отстоящем от Красногорска на расстоянии в одну бутылку пива, разговоры с ещё менее известным поэтом Святославом Смирновым?"},{"kind":"paragraph","text":"Я понял, что совершенно не хочу такого продолжения вечера. Но, если выбирать из этих трёх вариантов, лучший на сегодня — Святослав Смирнов."},{"kind":"paragraph","text":"Когда я впервые оказался у него дома, то почувствовал когнитивный диссонанс. Квартира в обычном пятиэтажном доме. Не панельном, правда, а кирпичном. Входная дверь обита дешёвым материалом. Когда она открылась, я увидел обшарпанные стены. В некоторых местах обои были просто поцарапаны, в некоторых — оторваны. Из коридора была видна старая стенка, заклеенная дешёвой клейкой лентой. И чувствовался не очень приятный запах. Он не бил в нос, но давал о себе знать, как, например, даёт о себе знать слепой, постукивая по тротуару тросточкой."},{"kind":"paragraph","text":"И в то же время в коридоре стоял факс, потом я увидел большой телевизор в комнате и компьютер последней модели, рядом с которым находился принтер."},{"kind":"paragraph","text":"Как-то это не вязалось со всем остальным."},{"kind":"paragraph","text":"Чуть позднее всё выяснилось. У Святослава была больная маленькая дочь. Проблемы с психикой. Этим и объяснялись обшарпанные стены, заклеенные дверцы стенки, а также запах — за ней приходилось постоянно стирать одежду."},{"kind":"paragraph","text":"Кроме дочери, у Святослава, пожалуй, не было проблем. Его отец прилично зарабатывал и не был скупым для него. Жена у Святослава была симпатичной, училась в аспирантуре. Ещё у него был старший брат — полковник ФСБ. Звали его Архип. Странноватое имя для человека из спецслужб."},{"kind":"paragraph","text":"Я уже решил, что поеду к Святославу, как познакомился с двумя парнями (как — не помню), оказавшимися почитателями Баяна Ширянова — вот она, слава! — и собирающимися в Москву, чтобы вмазаться «винтом». Совершенно непонятным образом наш разговор привёл нас к единодушному мнению: я тоже должен поехать с ними. Похоже, тот день был днём открытых наркодверей и притонов."},{"kind":"paragraph","text":"Но тут я сообразил, что если Баян Ширянов — это человек мне известный, проверенный, я даже знаю его настоящее имя, то эти двое могут оказаться кем угодно. Гоп-стоперами, хулиганами, масонами, психами… Что это за птицы вообще? Может, голубки или бакланы?"},{"kind":"paragraph","text":"Мы стояли на той стороне платформы, откуда поезда шли на Москву. А в моей голове шла работа мысли. Кроме «винта», который меня если и интересовал, то не более, чем кубок Гагарина интересовал Германа Титова, мои новые знакомые соблазняли меня походом в клуб «Швайн», где сегодня ночью будет интересная вечеринка."},{"kind":"paragraph","text":"Поезда на Москву не было, но пришёл поезд из Москвы. Он осветил своими огнями перрон. Из него вышли пассажиры. И тут я увидел, как одна девушка не просто посмотрела в мою сторону, а буквально уставилась на меня."},{"kind":"paragraph","text":"— Алексей, привет! — радостно закричала она и бросилась ко мне, широко распахнув руки."},{"kind":"paragraph","text":"Я никогда раньше не видел эту девушку. Более того, меня никогда не звали Алексей."},{"kind":"paragraph","text":"— Привет! — тоже закричал я и принял её в свои объятия."},{"kind":"paragraph","text":"Подумав секунду, поцеловал."},{"kind":"paragraph","text":"Она немного удивлённо посмотрела на меня. Тут я понял, что девушка подшофе, и изрядно. Лучше было бы сказать, что она уже надшофе. Её глаза были счастливыми."},{"kind":"paragraph","text":"— Ты куда пропал на столько? — спросила она, крепко держа меня."},{"kind":"paragraph","text":"— Уезжал. Вот, только вернулся, — сказал я и повернулся к парням: — Не судьба, ребята. Потом как-нибудь. Девушку свою встретил, сами понимаете."},{"kind":"paragraph","text":"И с лёгким сердцем пошёл со своей новой знакомой вниз по лестнице с перрона."},{"kind":"paragraph","text":"Конечно, через какое-то время она поняла, что ошиблась, но было это уже у меня в комнате. Звали её, насколько я помнил, Лена. Мы виделись с ней потом раза четыре, пока я не уехал жить в Москву. Это было ещё то благословенное время, когда мобильные телефоны встречались далеко не у всех, интернет казался диковинной забавой, а вода была слаще. Общее впечатление иногда портил первый президент России, но, как от вампира чеснок, от него помогал избавиться выключенный телевизор. Правда, это было не самое надёжное средство."},{"kind":"paragraph","text":"Вот на этом месте воспоминаний мне пришлось вернуться в 17-й год XXI века. «Тушинская». Я вышел из метро. И по привычке направился на платформу электропоездов, хотя на автобусе было, пожалуй, удобнее. Но об этом я подумал уже стоя перед расписанием. Мой поезд будет через десять минут."},{"kind":"paragraph","text":"Десять минут. 600 секунд моей, например, жизни. Я достал смартфон и подсчитал, сколько их прошло с того момента, когда я рассматривал другое расписание. У меня получилось 839 808 000. Что-то весьма среднее между номером мобильного телефона и весьма недурной бесконечностью, учитывая аж три восьмёрки."},{"kind":"paragraph","text":"А в том году восьмёрок не было. Только один, две девятки и ноль. Оставалось 100 дней до приказа. Мне оставалось служить в армии совсем немного. Это наполняло оптимизмом. Служил я в тайге. И оказаться на Большой земле можно было двумя путями: на маленьком самолёте или на большом автомобиле. Автомобилю, правда, предстояло преодолеть две паромные переправы. Мы, дембеля, рассматривали оба варианта."},{"kind":"paragraph","text":"Вместе со мной служил парень с Украины. И был он действительно хохлом как в хорошем, так и плохом смысле. Мы с ним ладили, никогда не конфликтовали. Даже тогда, когда он (дело-то было в девяностом) всё больше и больше дрейфовал в сторону «неньки-Украины». Ещё он был антисемитом, но выборочным. Вообще, евреи ему не нравились. Но Хазанова, Горина, Жванецкого и Валерию Новодворскую он обожал. Причём последнюю — особенно сильно. Даже ни разу её не видев. Он просто прочитал, что она лидер демократического союза, который стоит за самоопределение всех союзных республик."},{"kind":"paragraph","text":"Но антисемитом оставался всё же более жёстким, чем Новодворская — антисоветчицей."},{"kind":"paragraph","text":"Однако для меня было глубочайшим шоком, когда я увидел как-то тетрадный лист, на котором его рукой было крупно написано: «Расписание погромов». А внизу — даты. Вплоть до минут."},{"kind":"paragraph","text":"Именно эти минуты заставили меня понять, что я неправильно прочитал. И мой сослуживец просто написал «Расписание паромов». Так, на всякий случай."},{"kind":"paragraph","text":"Из окна электрички, которое принадлежало первому декабря семнадцатого года, я смотрел на пробегающий пейзаж."},{"kind":"paragraph","text":"Куда я еду? Зачем? К кому?"},{"kind":"paragraph","text":"Михаил Сарыч, скорее всего, мёртв. Он был хорошим поэтом, но это не спасло от смерти, а, пожалуй, наоборот. Михаил, несмотря на мои уговоры не делать этого, продал свою комнату в коммуналке семнадцать лет назад, полагая, что напишет великий роман и разбогатеет. Купит квартиру и видеомагнитофон. Человек, мечтающий купить видеомагнитофон в последнем году XX века, не имел никаких шансов выжить в XXI."},{"kind":"paragraph","text":"Олег Фомин-Шахов умер чуть более месяца назад. 40 дней будет как раз в день моего отъезда в Питер. Как-то он рассказывал, что его бабушка, в прошлом — оперная певица, называвшая меня Дием: «Олег, тебе звонил Дий». Она неправильно понимала в детстве слова песни «Любимый город», там, где «В далёкий край товарищ улетает — ла-ла, ла, ла, ла-ла-ла-ла — любимый город в синей дымке тает»… Ей слышалось вместо «в синей дымке тает» — «синий дым Китая»."},{"kind":"paragraph","text":"Поезд остановился на станции Павшино. Я вышел и огляделся вокруг. Всё изменилось. Строения, деревья, люди и, главное, я. Для этого мне надо было приехать сюда и оглядеться, чтобы увидеть себя."},{"kind":"paragraph","text":"Стоит ли проехать ещё немного, чтобы встретиться со Святославом? Я давно ведь уже знаю, что нельзя войти в одну и ту же реку дважды. Можно только дважды упасть в одну и ту же лужу. Или всё же рискнуть? Вдруг, пусть на короткий миг, время остановится? Вдруг на несколько секунд я вернусь на двадцать лет назад?"},{"kind":"paragraph","text":"Я действительно чувствовал грусть. Нет, не стоит пытаться вернуть прошлое. Не стоит пытаться войти в одну и ту же реку дважды. И нет причин падать в лужу."},{"kind":"paragraph","text":"Я вытащил смартфон и набрал номер домашнего телефона Святослава. Это был редкий номер, который я помнил."},{"kind":"paragraph","text":"Трубку взял его отец. Он приветливо со мной поздоровался. Мы поговорили. Да, через два дня поминки Олега, Святослав очень расстроен — они были друзьями."},{"kind":"paragraph","text":"— Как Архип? — спросил я, вспомнив почти забытое имя старшего брата Святослава, служившего когда-то в ФСБ полковником."},{"kind":"paragraph","text":"— Отлично. Сейчас на Кубе работает."},{"kind":"paragraph","text":"Мы ещё о чём-то поговорили и попрощались."},{"kind":"paragraph","text":"Я пошёл и купил билет назад, в Москву."},{"kind":"paragraph","text":"Что ж, я не снялся в телепередаче, не сходил на фестиваль «Железный марш», не вернулся в прошлое, не вошёл в одну и ту же реку второй раз, у меня нет кота, но зато теперь я знаю, как зовут нашего человека в Гаване."}]'::jsonb,
  '2023-12-31T12:00:00.000Z'
)
