INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd4-monstr-iz-stekla-betona-i-asfaltnoy-kroshki',
  'Монстр из стекла, бетона и асфальтной крошки',
  (SELECT id FROM "Authors" WHERE name = 'Василий Подкованный' ORDER BY id LIMIT 1),
  'mrd4/mrd4-monstr-iz-stekla-betona-i-asfaltnoy-kroshki.jpg',
  'data:image/jpeg;base64,',
  1586,
  1182,
  'Я живу в одном из окраинных районов Москвы. Сама Москва — город большой, шумный, и, чтобы рассказать о нём в полной мере, не хватит и целого дня. А потому расскажу о своём доме, своём районе. Мои предки, а именно бабушка',
  '[{"kind":"image","path":"mrd4/mrd4-monstr-iz-stekla-betona-i-asfaltnoy-kroshki.jpg","caption":null},{"kind":"paragraph","text":"Я живу в одном из окраинных районов Москвы. Сама Москва — город большой, шумный, и, чтобы рассказать о нём в полной мере, не хватит и целого дня. А потому расскажу о своём доме, своём районе. Мои предки, а именно бабушка с дедушкой, жили в Тропарёво. Сейчас это современный район с развитой инфраструктурой, стадионами и целой Олимпийской деревней в придачу!"},{"kind":"paragraph","text":"А когда-то здесь несла свои чистые воды река Очаковка. А на её левом берегу в обрамлении цветущих яблоневых садов стояло село Тропарёво, а вокруг, насколько хватало взгляда, расстилались поля и огороды, а вдалеке кипела Москва…"},{"kind":"paragraph","text":"Деревни не стало в 1981 году — последние дома снесли весной, и всё вокруг было застроено типовыми многоэтажками. Вырубили сады и проложили Рузскую улицу. Лишь церковь осталась напоминанием о прошлом района. Здесь жили мои предки. Моим старикам, бабушке и дедушке, крестьянам села, всю жизнь прожившим у земли, дали двушку с видом на бывшие монастырские сады, ставшие позже Тропарёвским парком."},{"kind":"paragraph","text":"Канувшему в Лету селу, своей родине, я посвящаю эту зарисовку."},{"kind":"paragraph","text":"— Знаешь, временами такое чувство внутри, аж распирает! — Люба сильнее прижалась ко мне, положив свою русую голову мне на грудь."},{"kind":"paragraph","text":"— Какое?"},{"kind":"paragraph","text":"— Ну ты, конечно, умный! — Я не видел лица девушки, но сразу представил нахмуренные брови, надутые губы: когда она сердилась, то сильно походила на забавного нахохлившегося зверька. — Разве можно такое в одно словечко уместить?"},{"kind":"paragraph","text":"— Про одно слово речи не было — говори сколько нужно, — я сорвал сочный колосок, вставив в рот."},{"kind":"paragraph","text":"— Ну… — не сразу ответила она. — Бывает, хочется всё объять! Землю, рожь, шелест ветра в ветвях берёзы у нашей избы. Солнце, небо, поля и…"},{"kind":"paragraph","text":"— И?"},{"kind":"paragraph","text":"— И тебя."},{"kind":"paragraph","text":"Я почувствовал, как она обнимает меня, и крепко прижал её в ответ."},{"kind":"paragraph","text":"«Хорошо быть влюблённым, — глядя в знойное июльское небо, думал я. — Всё вокруг кажется в новинку, всё словно омытое дождём — яркое, свежее…»"},{"kind":"paragraph","text":"Вдалеке, у дороги, гудел колхозный трактор, с дороги ветер доносил перезвон колокольчиков и мычание коров."},{"kind":"paragraph","text":"Быстро сделав все необходимые дела, мы с Любой с утра пораньше улизнули с колхозного двора сюда, в рожь. Разморённая духотой летнего дня, девушка посапывала на моей груди, а я думал о будущем. Об учёбе, работе в большом городе, куда увезу Любку с собой, о женитьбе…"},{"kind":"paragraph","text":"Я открыл глаза. Сам того не заметив, задремал."},{"kind":"paragraph","text":"Вокруг всё потемнело, словно укутанное тенью. Я привстал, разбудив Любу, — та, ворча, принялась тереть кулачками заспанные глаза."},{"kind":"paragraph","text":"— Ты чего?"},{"kind":"paragraph","text":"— Слышишь? — я обеспокоенно посмотрел на неё. Земля дрожала, откуда-то издалека нёсся всё сильнее нарастающий гул."},{"kind":"paragraph","text":"Я вскочил и увидел поверх волнуемой ветром нивы…"},{"kind":"paragraph","text":"Сложно было описать увиденное как-то конкретно. Оно не имело формы и походило на ком стальных прутьев, балок, бетона и поблёскивающего на солнце стекла. Нечто поднималось вверх и стремительно приближалось к нам, погребая под собой золотую рожь, берёзы урочища, дававшего прохладу колхозным пахарям в самую лютую жару, вьющуюся дорогу…"},{"kind":"paragraph","text":"— Что это?!"},{"kind":"paragraph","text":"— Не знаю… — прохрипел я, не сводя глаз с «бетонного вала». — Но оно ползёт на нас. Бежим!"},{"kind":"paragraph","text":"Я взял девушку за руку, и мы побежали сквозь рожь."},{"kind":"paragraph","text":"Мы выбежали на дорогу и увидели стоявший в низине трактор. Дядя Макар, пожилой тракторист, смолил козью ножку, не отрываясь от фантастического зрелища."},{"kind":"paragraph","text":"— Дядя Макар! — мы со всех ног побежали к трактористу. — Что это?!"},{"kind":"paragraph","text":"— Ничего хорошего, — бросив окурок в придорожную пыль, он закашлялся. — Бегом в деревню, молодёжь! Предупредите Владимира Андреевича, ну!"},{"kind":"paragraph","text":"— А вы?! — всхлипнула Любка."},{"kind":"paragraph","text":"— А я не могу трактор бросить… — не глядя на нас, тракторист пошёл к застывшей махине. — Поломало его немного, но ничего, колхозное имущество этому явлению не сдам! А вы бегите, живо!"},{"kind":"paragraph","text":"Мы развернулись и побежали. Некоторое время мы слышали позади себя тракторный гул, а потом в усиливающемся грохоте надвигающегося вала стих и он."},{"kind":"paragraph","text":"Мы бежали через рожь, напрямки к селу. Вот уже показались огороды, околица…"},{"kind":"paragraph","text":"Мы пробежали через обезлюдевшую улицу прямиком в колхозный двор."},{"kind":"paragraph","text":"— Владимир Андреевич! Владимир Андреевич! — я с ходу ворвался в правление, но там было пусто. Только звенела о край стакана ложечка да гудели стёкла, сотрясаемые приближающимся валом."},{"kind":"paragraph","text":"— Что там?! — в глазах девушки плескался страх."},{"kind":"paragraph","text":"— Никого нет… — бледнея, пробормотал я. Однако мгновеньем позже я встрепенулся. — Смотри!"},{"kind":"paragraph","text":"Пока мы бежали, бетонная лава уже докатилась до села и принялась растекаться по улице."},{"kind":"paragraph","text":"Мы кинулись бежать, но, куда ни кинь взгляд, везде мы натыкались на ощерившуюся арматуру, бетон, стекло…"},{"kind":"paragraph","text":"— К церкви! — заорал я, увлекая девушку за собой. — Заберёмся на колокольню!"},{"kind":"paragraph","text":"Мы ворвались в отворённые, проржавевшие церковные ворота, оказавшись перед храмом. Церковь в нашем селе закрыли ещё до войны, приспособив под зернохранилище. Высокую колокольню хотели взорвать, чтобы не служила ориентиром для немецких лётчиков, но в этом отпала надобность — немцев отогнали от Москвы. А колокольню приспособили под метеорологический пост."},{"kind":"paragraph","text":"Задыхаясь, мы вбежали наверх. Перед нами от края до края раскинулось море бетона и железа, захлёстывающего сельские проулки, ломающего деревянные избы. Волны стали и асфальта погребали под собой огороды и пшеничные поля, луга для выпаса. Треснул крепкий сруб деревенского клуба, бетон погрёб под собой сельсовет, колхозные амбары, цветущие сады…"},{"kind":"paragraph","text":"Из широко открытых глаз девушки по щекам ползли слёзы, а я застыл, охваченный ужасом."},{"kind":"paragraph","text":"Бетонная лава обтекала церковную ограду, не заливаясь внутрь. Мы смотрели с колокольни на бетонное море, быстро расширяющееся и убегающее на многие километры вокруг. Из бесформенной агонии металла, бетона, стекла и асфальта начали подниматься наросты, с каждым мгновеньем приобретая форму квадратов, рвущихся ввысь."},{"kind":"paragraph","text":"Мы не успели отойти от шока, как поняли, что вокруг, на месте села, раскинулись бетонные соты с тысячами тысяч окон, отражающих закатный свет. Гул удалялся, пока не стих вовсе."},{"kind":"paragraph","text":"— Вроде бы прекратилось… — тихо сказал я."},{"kind":"paragraph","text":"Люба посмотрела на меня. Не говоря ни слова, я притянул её к себе. Сколько мы так простояли — ума не приложу. Наконец она сказала:"},{"kind":"paragraph","text":"— Пошли посмотрим."},{"kind":"paragraph","text":"Мы спустились с колокольни, вышли в открытые церковные ворота и оказались в новом, невиданном доселе мире. Здесь не пели птицы, не мычала скотина, не гудел трактор… Даже ветер, так приятно шелестевший листвой деревьев, теперь мёртво выл среди бетонных коробов."},{"kind":"paragraph","text":"— Слышишь?"},{"kind":"paragraph","text":"Я напряг слух. Вдалеке я услышал игру гармони, разносимую ветром на многие километры."},{"kind":"paragraph","text":"— Это же дед Кузьма играет! — Люба радостно засмеялась. — Пошли скорее!"},{"kind":"paragraph","text":"И действительно: в переборах гармошки я узнал лихую игру главного сельского балагура, старика Кузьмы, ветерана Гражданской и Великой Отечественной. Играл дед Кузьма редко, но после пары стопок на праздник за гармонь брался всегда. И так лихо и душевно отыгрывал…"},{"kind":"paragraph","text":"Музыка привела нас к одному из бетонных коробов — она неслась откуда-то с верхних этажей."},{"kind":"paragraph","text":"— Страшно, — взяв меня за руку, Люба прижалась ко мне всем своим существом."},{"kind":"paragraph","text":"— Не бойся, — я крепко сжал её ладонь. Меня самого пробирала дрожь при взгляде на этот бетонный улей. Но, переборов страх, мы вместе шагнули в чёрный зев входа…"},{"kind":"paragraph","text":"Всё выше и выше мы поднимались по лестнице, держась за стальные перила. На восьмом этаже музыка стала невероятно отчётливой."},{"kind":"paragraph","text":"— Это здесь, — я кивнул вправо, на хлипкую деревянную дверь."},{"kind":"paragraph","text":"Я потянул за ручку — дверь оказалась не заперта. Как только мы вошли в пустую комнату, игра сразу прекратилась."},{"kind":"paragraph","text":"— Дед Кузьма? — Люба принялась бегать по пустой квартире. — Дед Кузьма!"},{"kind":"paragraph","text":"Никакого ответа, лишь эхо, отражающееся от холодных бетонных стен…"},{"kind":"paragraph","text":"Порыв сквозняка захлопнул хлипкую дверь."},{"kind":"paragraph","text":"— Что же это? — Люба кинулась в прихожую. — Саша, тут дверь заперта! Не могу открыть! Помоги!"},{"kind":"paragraph","text":"— Иди сюда, Люб… — отстранённо сказал я, подойдя к широкому окну."},{"kind":"paragraph","text":"— Саш, нас заперли тут, что же ты… — она подошла ближе, принявшись трясти меня за плечо, но тут осеклась."},{"kind":"paragraph","text":"Мы смотрели в окно на улицу, где, повинуясь неведомой, сокрушительной силе, кипела жизнь."},{"kind":"paragraph","text":"Именно она заключала небольшую чистую речушку, в которой я когда-то ловил карасей, в коллектор. Она перепахивала землю, закладывая туда мириады труб и кабелей, подключая их к бетонным коробам."},{"kind":"paragraph","text":"Там, где ещё недавно пылило, бредя на выпас, стадо коров, теперь раскинулась широкая полоса шоссе. Как старинная скатерть узорами, шоссе было расписано разметкой, указателями, светофорами. Магистраль сначала понемногу, а затем всё больше заполнялась вопящими сигнализацией машинами, вставшими в бесконечной пробке."},{"kind":"paragraph","text":"На домах расцветали, как взрывы салюта на День Победы, неоновые вывески, а красные флаги и лозунги быстро сменились мигающими реклaмными баннерами. Проложенные тротуары заполнились спешащей толпой, и море огней зажглось в дотоле чёрных провалах окон…"},{"kind":"paragraph","text":"Моя отяжелевшая, покрытая вздутыми варикозом венами рука по-прежнему крепко держит руку Любы. Она стоит рядом со мной, и в отражении стекла мы видим покрытых морщинами стариков."},{"kind":"paragraph","text":"А вокруг, куда ни кинь взгляд, расстилается закованная в асфальт и неоновый свет Москва…"}]'::jsonb,
  '2023-12-31T12:00:00.000Z'
)
