INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd4-trevozhnyy-chelovek',
  'Тревожный человек',
  (SELECT id FROM "Authors" WHERE name = 'Николай Гиливеря' ORDER BY id LIMIT 1),
  'mrd4/mrd4-trevozhnyy-chelovek.jpg',
  'data:image/jpeg;base64,',
  1586,
  915,
  'Памяти Лёши Здравствуй',
  '[{"kind":"image","path":"mrd4/mrd4-trevozhnyy-chelovek.jpg","caption":null},{"kind":"paragraph","text":"Памяти Лёши Здравствуй"},{"kind":"paragraph","text":"Чёрный экран. Слышны нарастающие шаги. Позвякивание ключей. Щелчок отпираемого замка. Дверь захлопывается, не забыв скрипнуть. Зажигается свет в коридоре, и вот перед зрителем разувается молодой человек Миша."},{"kind":"paragraph","text":"Ванная комната. Вода льёт тонкой струйкой (Миша умывается). Зал. Миша включает телевизор, из которого диктор начинает вещать новости. Канал переключается. Теперь подборка страшных ДТП. Следующий. Эпидемия унесла миллионы жизней. Следующий. Играет дешёвая попса. Следующий. Сплетни о звёздах. Следующий. Блогеры зарабатывают миллионы, крутя жопами."},{"kind":"paragraph","text":"Интенсивность переключения каналов нарастает, попутно возрастает и градус несуразицы современных тенденций. На фоне развернувшейся какофонии накладывается громкий звук учащённого биения сердца."},{"kind":"paragraph","text":"Миша с силой вдавливает красную кнопку пульта. Звуки резко пропадают, заставляя тишину надолго повиснуть в воздухе. Грудная клетка Миши нервно пульсирует."},{"kind":"paragraph","text":"Раздаются отдалённые шаги. Дверь шумно открывается. С работы вернулась мама Миши."},{"kind":"paragraph","text":"МАМА. Привет, сынок."},{"kind":"paragraph","text":"МИША. Привет, мам."},{"kind":"paragraph","text":"Женщина подходит к сыну, забирает пульт из его рук и включает канал, на котором идёт передача о дикой природе. Диктор рассказывает о выживании хищников Африки."},{"kind":"paragraph","text":"МАМА. Ты уже поужинал?"},{"kind":"paragraph","text":"МИША. Ещё нет. Хотел тебя дождаться."},{"kind":"paragraph","text":"МАМА. Отлично. Тогда поставь разогреваться борщ из холодильника. Я колбасы купила. Сейчас могу целого слона проглотить, так проголодалась!"},{"kind":"paragraph","text":"Мама удаляется в спальную комнату, чтобы переодеться."},{"kind":"paragraph","text":"Кухня. Миша начинает выполнять просьбу. Открывается холодильник. Звон алюминиевой крышки кастрюли, слетевшей по неосторожности. Наполнение советских тарелок красной жидкостью с редкими кусками животной плоти. Гудение микроволновки."},{"kind":"paragraph","text":"Всё разогрето. В тусклом свете сидят мать и сын. Первые две минуты они молча дуют на еду, изредка её прихлёбывая."},{"kind":"paragraph","text":"МИША. Не сильно горячо разогрел?"},{"kind":"paragraph","text":"МАМА. Нет, сейчас уже остынет."},{"kind":"paragraph","text":"МИША. Хорошо."},{"kind":"paragraph","text":"МАМА. Как твой день прошёл?"},{"kind":"paragraph","text":"МИША. Обычно. Что может произойти интересного на выдаче заказов?"},{"kind":"paragraph","text":"МАМА. Ну, мало ли. Вдруг заходила очередная старая сумасшедшая, которая начала поднимать шумиху, хотя сама неправильно оформила заказ!"},{"kind":"paragraph","text":"МИША. Да нет, ты ведь давно ничего не заказывала."},{"kind":"paragraph","text":"МАМА. Тут не поспоришь!"},{"kind":"paragraph","text":"МИША. Лучше расскажи, как прошёл день у тебя."},{"kind":"paragraph","text":"МАМА. Ой, не спрашивай. Каждый день одна и та же песня. Пьяницы с разукрашенными лицами, переломанными пальцами и рёбрами. Переломанные дети, спортсмены. Сегодня вот ещё привезли в неотложку мотоциклиста. Весь разорванный, перебитый… живого места нет. Благо жив остался, уж это ли не чудо?"},{"kind":"paragraph","text":"А Зинка вон, ну ты помнишь, тётя Зина, младшая медсестра, со мной работает. Пухленькая такая, помешанная на своём маникюре. Ты ещё как-то потом полвечера смеялся над её дельфинами, когда она приходила в гости. Вот она действительно не даёт покоя!"},{"kind":"paragraph","text":"МИША. Понятно."},{"kind":"paragraph","text":"МАМА. Всё бегает от одного мужика к другому. Устраивает драму из своих интрижек. Ты представляешь, каково мне слушать каждый день её бредни?"},{"kind":"paragraph","text":"МИША. Не представляю."},{"kind":"paragraph","text":"МАМА. То один хахаль зовёт её под венец, то второй начал ревновать к каждому столбу. А потом, она будто специально даёт лазейки этим бабуинам, чтобы они прознали друг про друга. И вот вечные стычки эти… разборки! А сама Зинка рассказывает обо всём возмущённо, но я-то вижу, она в восторге от происходящего хаоса вокруг себя."},{"kind":"paragraph","text":"МИША. Ох уж эта Зинка…"},{"kind":"paragraph","text":"МАМА. И не говори! Подумываю уж прямо ей сказать, что не хочу больше слушать весь этот фарс, но разве она послушает меня?! Тут только один выход: рассориться с ней вдрызг. Но я не могу себе такого позволить, понимаешь? В моём возрасте люди редко когда заводят новых друзей. Уж неприлично. Нужно пользоваться тем, что нажил…"},{"kind":"paragraph","text":"МИША. Ага."},{"kind":"paragraph","text":"МАМА. Так что мой тебе совет: хватит сидеть вечно дома в свои выходные. Начни больше гулять, заводи новые знакомства, а то потом однажды проснёшься и поймёшь, что тебе глубоко за сорок, а ты один как сыч!"},{"kind":"paragraph","text":"МИША. Как ты перешла от тирады про тётю Зину до жизненных советов?"},{"kind":"paragraph","text":"МАМА. А вот так и дошла, сынок. Учись у меня, пока жива твоя старушка."},{"kind":"paragraph","text":"МИША. Ты вовсе не старушка."},{"kind":"paragraph","text":"МАМА. Ага. А вот эти морщины под глазами тебе ни о чём не говорят?"},{"kind":"paragraph","text":"МИША. Говорят только о том, что ты человек, и всё, мам. Правда. Ты ещё вполне хороша собой."},{"kind":"paragraph","text":"МАМА. Не говори ерунды! Мне твоя лесть не нужна."},{"kind":"paragraph","text":"МИША. Я говорю правду."},{"kind":"paragraph","text":"МАМА. Мелкий хитрый паршивец!"},{"kind":"paragraph","text":"МИША. Двадцать пять лет — возраст далеко не мелкого."},{"kind":"paragraph","text":"МАМА. Но всё же паршивца."},{"kind":"paragraph","text":"МИША. Спасибо. Посуду оставь. Я пойду, полежу немного и помою всё."},{"kind":"paragraph","text":"МАМА. Ой, герой нашёлся! На здоровье. Иди уж, сама помою. Тут две тарелки. Ты завтра отдыхаешь?"},{"kind":"paragraph","text":"МИША. Да."},{"kind":"paragraph","text":"МАМА. И у меня один выходной. Сходить в магазин со мной не хочешь после полудня? Купили бы тебе футболок. А то вон всё ходишь в одной и той же."},{"kind":"paragraph","text":"МИША. Я тебе говорил: у меня несколько одинаковых. Может и сходим…"},{"kind":"paragraph","text":"МАМА. Ладно. Свободен."},{"kind":"paragraph","text":"Сцена в комнате Миши. Стоит кровать. Письменный стол у окна. В углу затаился советский гардероб. Миша ложится. Его лицо не выражает никаких эмоций. В каком-то смысле даже становится немного страшно, особенно при таком тусклом освещении. Статичный взгляд уставился в потолок. Миша медленно засыпает."},{"kind":"paragraph","text":"Глубокая ночь. Перед взором зрителя появляется наружная часть окна с кирпичной стеной, в чьих внутренностях спит Миша. Нарастающий звук комара, который после обрывистого писка пропадает. Миша медленно приподнимается с кровати."},{"kind":"paragraph","text":"МИШA. На часах полтретьего. Какая многословная тишина… Незнакомой мне кажется эта комната в первые секунды."},{"kind":"paragraph","text":"Снова снился пляж с кристальным морем. Солнце над головой приятно пекло, не обжигая. Вдали, ближе к горизонту, проплывал всё тот же грузовой корабль, но при таком отдалении сложно сказать, насколько он был большой, да и смысла в его размере нет. Так мне кажется каждый раз…"},{"kind":"paragraph","text":"Беззаботное чувство наполняет тело, принадлежащее уму. Что я знаю о себе в этом повторяющемся сновидении? Пожалуй, ничего, что только добавляет прелести, иначе я не смог бы чувствовать лёгкость, если б знал о себе слишком много."},{"kind":"paragraph","text":"Почему все приятные сны обрываются на одном и том же месте? Почему я не могу продолжить видеть желанное?"},{"kind":"paragraph","text":"Несправедливость. Точнее, это та несправедливость, которую я сам выстроил высокой стеной, сознательно отгородив внешнее сознание от чего-то большего, нежели чем владею в…? Думается, именно «начальство сверху» не даёт желать большего; стремиться к этому большему. А все сны — то маленькое, что ещё пытается прорваться ко мне; докричаться."},{"kind":"paragraph","text":"Заключённый в тюрьму. В одиночной камере сижу я. Тот другой «я», желающий свободы, но нынешняя версия уж больно хорошо выполняет свою работу."},{"kind":"paragraph","text":"Каждый день я выстраиваю всё новые препятствия, а в довершение к предпринимаемым ухищрениям — умудряюсь «себе желанному» подкидывать кости в виде утешений, что скоро всё наладится; что срок заточения не вечен. Ты ведь не убийца. Ты не ел детей. Не насиловал годами, да и вообще, если посмотреть на себя со стороны, то вполне законопослушный адекватный человек."},{"kind":"paragraph","text":"Тогда что я делаю в тюрьме? Что забыл за толстыми решётками, не имеющими реальных стен? Просто так ты себя не осудил. Нет. Ты заточён не по ложному обвинению. Есть основания полагать… точнее: предположить, что на твоей гипотетической душе есть серьёзный грешок! И кроется этот грех именно в добровольном заточении. Эта мысль не даёт мне покоя вот уже какую ночь. Каждый раз одно и то же."},{"kind":"paragraph","text":"«Счастливый я» выдёргивается, умирает в пиковый момент своего равновесия, оказываясь в новой-старой комнате."},{"kind":"paragraph","text":"Миша медленно встаёт с кровати. Подходит к окну. Глухой скрип открывшейся форточки. Где-то вдали проехала машина, ещё дальше слышна приглушённая ругань. Что-то разбивается. Взгляд Миши устремляется в зрительный зал, внимательно начиная всматриваться в каждого присутствующего."},{"kind":"paragraph","text":"МИША. Как мне здесь душно! Тесно. Кто бы мог подумать, что я буду просыпаться каждую ночь не в силах провалиться в противопоставление? Тонкая струйка свежего воздуха чарует. Я чувствую прохладу лицом, но от этого тело словно ещё глубже проваливается в невыносимую духоту. А на улице такая тишина… Сейчас другие люди беззаботно спят в своих домах, на своих мягких (и не очень) кроватях. Интересно, что видят они?"},{"kind":"paragraph","text":"Я просто уверен: очень многие видят сейчас кошмары. Ужасные пустоты в привычных формах пытаются сожрать их, а они кричат, убегают… но не просыпаются. Только наутро они как бы вскочат, осмотрятся и вздохнут с облегчением. Скоро на их сонном лице будет играть искренняя улыбка. Они подумают: «Боже, это всего лишь сон!» И, обрадованные этим фактом, начнут свой насыщенный и удивительный день, полный радости."},{"kind":"paragraph","text":"А что же остаётся мне? Таким, как я? Просыпаясь, уходить от улыбки, погружаясь в неподдельный ужас, и уже вопить: «Нет, боже! Это был всего лишь сон!» День ещё не настал. Ночь стоит тихая. Головы крепко спят. Некому написать. Никто не слышит мой жалкий стон. И к лучшему ли это? Думаю, к лучшему, но не для меня."},{"kind":"paragraph","text":"Почти невозможно быть сильным в одиночку. Это правда. Я говорю это в пустоту, пытаясь хоть с кем-то поговорить. И этот кто-то всё понимает. Пустоте тоже страшно, как и мне; как и кому-то ещё на этой Земле. Я успокаиваю себя, когда тело начинает дрожать; когда начинает погружаться в агонию за неимением удовлетворительного лживого спасения… Я успокаиваю себя рассуждениями. Хотя, наверно, пока только нагнетаю."},{"kind":"paragraph","text":"Убеждать себя, что ты справишься, — значит раздражать себя. Выбешивать банальной глупостью. Я ведь не автоответчик в телефоне. Вот и получается, что для поиска равновесия нужен диалог. Даже разговор с пустотой, с самим собой. Это крайний случай, но зачастую другого и не представляется. Я мог бы поговорить с мамой. Мог бы даже поговорить с единственным другом, но собственная эмоциональная неполноценность приведёт только к медленному, но верному дистанцированию."},{"kind":"paragraph","text":"Иногда хочется просто взять, отбросить свою роль, сняв маску с лица. Зарыдать самыми горькими слезами, бросившись в мамины объятия. И только повторять: «Мама, мама… как же мне больно, мама». А она бы гладила по голове, убаюкивая, как в детстве, и всё повторяла бы: «Ну что ты, что ты, сынок, не плачь. Всё хорошо. Что случилось? Расскажи мне. Ты можешь доверить мне самую страшную тайну»."},{"kind":"paragraph","text":"И вот тут появляется главная загвоздка. Как объяснить близкому человеку… как сказать даже просто человеку, что у тебя нет настоящей причины плакать? Нет у тебя тех проблем, по которым обычно плачут «нормальные» люди."},{"kind":"paragraph","text":"У тебя ничего не болит, физически ты полностью здоров. Работа твоя даёт возможность хорошо питаться и быть опрятным. Родился ты симпатичным и не глупым. И всё, казалось бы, так понятно и просто. Оканчиваешь школу, получаешь профессию в колледже и институте, а после начинаешь работать. Заводишь семью, машину, квартиру. Воспитываешь, растишь и молишься на счастливую смерть в морщинах. Мир прост как пять пальцев!"},{"kind":"paragraph","text":"Но вот когда не находишь простых причин несчастий — вот тогда на тебя и начинают смотреть как на дурака. Мол, какого чёрта?! Ты совсем спятил? Или ты из полярников?"},{"kind":"paragraph","text":"А что, если я скажу, что все эти так называемые «помешанные» — просто жертвы? Понятное дело, у кого-то из них есть физические причины, по которым и настиг недуг, но таких я не беру в расчёт, хотя этот факт не умаляет их несчастья. Речь же сейчас идёт о несчастье совсем иного толка: о неумении жить."},{"kind":"paragraph","text":"В этой комнате я снова чувствую ограничение. Очень тяжело думать в маленьком клочке пространства. Летняя ночь снова манит к себе, покровительствуя возможностью, оставшись в тени, выйти на мыслительный свет, где есть место развернуться."},{"kind":"paragraph","text":"Звуки застёгиваемой молнии на джинсах. Миша одевается. Тихие шаги. Реквизит окна убирается. До зрителей доносится скрежет ключей, открывающих входную дверь."},{"kind":"paragraph","text":"По обе стороны сцены вырастают панельные дома и освещение от уличных фонарных столбов. Миша на улице провинциального городка."},{"kind":"paragraph","text":"МИША. Неумение жить, да… Именно так мне видится собственное заболевание. Не хочу показаться эгоистичным, поэтому смею предположить, что «неумение жить» в целом присуще очень многим людям. За доказательствами далеко ходить не надо, достаточно каждому вспомнить свою мечту, стремление… или даже не так. Для начала достаточно вспомнить себя в детстве. Какое было представление о своём будущем?"},{"kind":"paragraph","text":"Детство помнится смутно. Но обрывки всегда останутся на поверхности, как памятник чему-то светлому. Вот я помню маму и отца, когда они ещё были вместе. Сидят молодые и красивые на старом диванчике, и ничего им для счастья не надо, ведь теперь у них есть я. На тот момент в мыслях не было этого счастья, но теперь, вспоминая, я бы хотел вернуться в ту секунду, только чтобы просто улыбнуться этим людям. Как замечательно не знать, что мама и папа — это ещё и люди по отдельности со своими потребностями, своими желаниями и целями; и когда их цели не совпадают, когда собственная неудовлетворённость перевешивает, тогда светлый мир маленького человечка может исказиться потерей."},{"kind":"paragraph","text":"Я вспоминаю первый увиденный мультик, где мальчик чуть старше меня самого тогдашнего отправляется в путешествие на ракете. Он видит много новых мест и существ. Все его зовут смелым и умным. Вот уже и я примеряю на себя эту роль, мечтая, что, когда подрасту, смогу также отправиться в путешествие на далёкие планеты. Но вот проходят года. Всё больше информации входит в мою жизнь."},{"kind":"paragraph","text":"В лет шесть я узнаю, что путешествовать на ракете — дело серьёзное и совсем не для маленьких детей. Что люди эти зовутся космонавтами, и, чтобы стать космонавтом, надо вырасти, пройти серьёзные подготовительные курсы, а после (если сильно повезёт) наконец стать тем самым мальчиком, только уже мальчиком за тридцать плюс лет. И отправишься ты не на другие планеты, а будешь сидеть в маленькой кабинке, летая вокруг орбиты Земли."},{"kind":"paragraph","text":"С возрастом мечты начинают скакать галопом, каждый раз становясь только проще. После несложившейся карьеры космонавта приходит идея заняться спортом. Уже юные глаза смотрят на спортсменов с телеэкрана, которые так счастливо выглядят на пьедестале почёта! Они благодарят всех своих родных и близких; говорят, как счастливы от того, чем занимаются. А после, через несколько лет, ты видишь в программе их же, правда, уже без малейшего намёка на улыбку. Они вяло рассказывают, как любимый спорт сломал им здоровье. Но самое смешное и потешное — что эти люди, посвятившие свою жизнь спорту, затем рвутся в политику, устраивая одну большую клоунаду. Но что-то я отвлёкся…"},{"kind":"paragraph","text":"Я просто хочу сказать, что счастлив тот человек, который смог найти своё предназначение с ранних лет и целенаправленно идёт к нему долгие годы. Ещё счастливы люди, которые меньше всех знают о жизни; их грубый ум огорожен готовыми пониманиями об окружении. Убивать — это плохо. После смерти их ждёт рай с приветливым богом и кучей знакомых. Ещё такие люди безоговорочно верят тем, кого показывают по телику. Они не проверяют информацию. Таким людям нет дела до предполагаемой истины. Иными словами: они не стремятся самостоятельно решить пример, а предпочитают быстренько скатать его у соседа по парте."},{"kind":"paragraph","text":"Неумение жить начинает формироваться как раз в тот момент, когда ты начинаешь задавать вопросы этому Миру. Начиная с самого начала: «А почему я — это я?»"},{"kind":"paragraph","text":"Образ Миши претерпевает метаморфозу, превращаясь в девочку Дашу. Уже она продолжает монолог о наболевшем."},{"kind":"paragraph","text":"ДАША. Кто я? По существу. У меня есть личность, но как мне ощутить её подлинность? Ведь невозможно, чтобы человек был индивидуальным. Просто невозможно! А я скажу: личность человека — это опыт окружения. А окружение — всегда общий формат. Такая простая мысль мало до кого доходит. Временами это сильно печалит, учитывая, что именно эта идея могла бы стать ключом к революции в социальной жизни."},{"kind":"paragraph","text":"Мне двадцать пять. И всё, что от меня требуют родители, так это уже хоть какого-нибудь жениха и внука. А меня спросили: хочу ли я? И как человек вообще имеет право просто по собственному капризу либо под напором общественного мнения создавать жизнь, обрекая ещё одно существо на тяготы силы притяжения?"},{"kind":"paragraph","text":"Никто не спрашивал меня: хочу ли я быть здесь. Эти посторонние, они твердят, что я теперь обязана. Так кто мне ответит на вопрос: кто же я? Получается, что я стала чьей-то прихотью без шанса выбора. Да, можно сказать, что спросить никак не получится, но если ты заводишь ребёнка, если хочешь его вот так приобрести для себя, то хотя бы удосужься сделать так, чтобы эта новая (навязанная только твоим желанием) жизнь могла получить нужный минимум."},{"kind":"paragraph","text":"Я говорю спасибо маме и папе. Спасибо, что вы пытались мне дать всё, что только можно. Но я также с полным правом говорю вам своё «не спасибо» за все разы, когда вы пытались сделать из меня собственность. Не спасибо вам за каждый раз, когда вы говорите, что я должна родить, должна выйти замуж, должна носить красивые платья, а ещё должна гулять, соблюдая ограничения, и только по причине того, что на улице выплодилась целая куча маньяков, которых тоже когда-то родили; не дали уверенности в себе, не дали понимания личных границ, а ещё той нужной обеспеченности, без которой нищее, обветшалое тело сломило и дух, сделав нравы не животными, а самыми ЧЕЛОВЕЧЕСКИМИ, в полном маразме этого слова."},{"kind":"paragraph","text":"Сейчас я иду по безлюдной улице. Мне немного страшно вот из-за таких несчастных, которые могут повстречаться на пути. Но в то же время мне приятно чувствовать своё нескованное тело. Пока я иду — я живу… И вопрос «кто же я?» остаётся с маленькой надеждой на возможность найти ответ."},{"kind":"paragraph","text":"Неумение жить тесно связано с этим вопросом. Много свободного времени создаёт большой поток мыслей, а они, в свою очередь, пытаются проникнуть в каждую клеточку имеющегося эмоционального опыта. Мы, люди, не можем постоянно быть счастливыми, а тем более несчастными. Нервная система не рассчитана на такие перегрузы. И вот свободное время как раз и становится площадкой, где весь эмоциональный опыт начинает кружить, завывать, создавая впечатление переполненной черепушки."},{"kind":"paragraph","text":"Неподготовленный «Я» в первую очередь очень болезненно чувствует негативные, упаднические мысли, олицетворяющие научность и логику. Наука вообще убивает наивную романтику, которая так необходима каждому. Под своим утверждением я могу смело расписаться и взять всю ответственность, ведь я человек, который потерял эту беспечность, наивность и светлую глупость, которые защищали меня."},{"kind":"paragraph","text":"Остаться с Миром вот так, обнажённой, — значит в первую очередь почувствовать свою уязвимость. Поначалу, когда я раздевалась, я думала, что моя нагота покажет истинную кожу человека; тогда я наивно считала, что отсутствие стеснения станет заразительным! Что сначала близкие, а потом их друзья, а затем друзья друзей начнут подхватывать эти нотки чистого и понятного. Ведь если посмотреть на это гипотетически, то честность во всём и везде, открытость и помощь, и даже принятие скопившегося неизбежного абсурда, то есть нашего существования, уже могло бы значить утопию, победу над всем плохим."},{"kind":"paragraph","text":"Но вот я открываюсь людям, отбрасываю ради них романтические маски, показываю себя настоящей. А все эти некогда друзья, родственники, возлюбленные — они просто начинают меня ненавидеть."},{"kind":"paragraph","text":"Моя открытость видится им пошлостью. Моя честность выглядит для них как снобизм и дань современной моде. А моё обнажённое тело вызывает у них стыд. Со всех сторон сначала появляются возмущённые косые взгляды, а ближе к вечеру, когда эти ЛЮДИ имеют возможность скрыть своё социально-приемлемое лицо, тогда уже в мой адрес летят оскорбительные слова: «Ты шлюха!» После слов в голову запускается мелкий щебень, а потом и вовсе особо жестокие и закомплексованные люди вываливают булыжник, раздрабливающий мои кости."},{"kind":"paragraph","text":"Поначалу я много плакала. Погружалась в страдание с головой. Такая несправедливость больше всего уничтожала во мне желание. Боль физическая же оставалась падающей тенью от моральной жестокости."},{"kind":"paragraph","text":"Что я смогла понять? Что рая на Земле никогда не будет; что весь ад мы возводим собственными руками, а попытка одного стать открытой дверью заканчивается полным его уничтожением."},{"kind":"paragraph","text":"Этап выживания — самый интересный. Когда я поняла, что не быть мне мною, я попыталась закрыться, стать снова не человеком, а девушкой. Той самой, которая любит готовить, постоянно обсуждает чужие отношения и всё мечтает о крепкой семье."},{"kind":"paragraph","text":"Признаюсь, в какой-то момент меня чуть ли не стошнило… Какая мерзкая и фальшивая я виделась самой себе! Это невыносимое чувство: каждый день притворяться! Ведь в действительности всё никогда не может стать как прежде."},{"kind":"paragraph","text":"Изменивший однажды снова изменит. Ударивший — снова ударит. А потерявший хоть раз наивность на свой счёт и эту Землю — всегда останется с оголёнными нервами."},{"kind":"paragraph","text":"Мои нервы оголены. Я сильно чувствую всю навалившуюся беду, но в то же время вижу в ней и спасение."},{"kind":"paragraph","text":"Главный проводник через страх — искусство. Или творчество. Каждый называет изрыгание собственного нутра с учётом уровня самомнения. Я никак не называю те полотна, что смею пачкать краской. Иногда мне кажется, что это мои дети; а иногда, когда изображённые образы вызывают животный страх, я начинаю считать их язвой. Неизменная проблема «неумения жить» тесно начинает сплетаться с вопросом «кто я?». Ведь за неимением вариантов получше этот кажется самым логичным. Хотелось бы в это верить, но шансы, как и во всём, крайне малы."},{"kind":"paragraph","text":"Из-за угла переулка появляется сам Миша. Он начинает идти справа от Даши."},{"kind":"paragraph","text":"МИША. Когда я впервые взял кисть в руки — я был счастлив. Мне хотелось рисовать натуралистичные пейзажи, а ещё — портреты. Удивительна история мастеров, что растянулись своими творениями на многие века, и вот теперь, когда уже не осталось внутренней культуры, эти личности всё ещё висят в музеях, собирая большим дядям монеты."},{"kind":"paragraph","text":"Утверждать, что ты рисуешь для себя, значит нагло врать. Не важно, что по итогу ты начинаешь иллюстрировать собственное безумие. Каждое вложенное усилие хочет продаться, хочет своего зрителя. И тогда возникает закономерный вопрос: «А тот ли я, кем хочу казаться?», или я хочу казаться больше, чем быть? Быть просто собой — уникальная вещь, но только из собственных глаз, ведь для других…"},{"kind":"paragraph","text":"ДАША. Я не значу ровным счётом ничего! Наверно поэтому стать популярным — одно из ключевых условий для освобождения себя. А кто меня осудит, кто скажет, что семья, что любовь благодарного ребёнка — важнее, тот будет ещё большим эгоистом, чем люди, усомнившиеся в честности такого пути."},{"kind":"paragraph","text":"Давайте честно. Семья — это доступный вариант только для того, чтобы стать важным для кого-то ещё. Нужным! И тогда спрашивается: а в чём различие? Только в сложности. Каждый выбирает свою иллюзию."},{"kind":"paragraph","text":"МИША. Поэтому никогда не осуждай других. Никогда. Я знаю, эта тишина впереди меня всё прекрасно слышит. Любой путь Homo видится мне именно в поиске ответа: «Кто же этот я?»"},{"kind":"paragraph","text":"Формулы для счастливой жизни просто не существует. Кто-то заводит большую семью. Кто-то всю жизнь гонится за деньгами. Третий находит наслаждение в извращениях, наркотиках, ничегонеделании, искусстве, музыке; в одиноких прогулках по выходным, в конце концов. Но разве перечисленное — не разрушение?"},{"kind":"paragraph","text":"ДАША. Вид постоянно бегущих людей вызывает головокружение. В час пик, когда я спешу на работу, становится очень страшно. Столько биологических машин куда-то спешит, о чём-то думает. И вот я — одна из этих машин, и может быть, именно сейчас кто-то думает про меня ровно то же самое. Мне хочется поговорить об этом несвязанном шквале вещей, но с кем?"},{"kind":"paragraph","text":"МИША. Почему люди так закрыты? Страх, который из поколения в поколение навязывают каждому новому сосуду? Иногда я думаю о том, что отдал бы всё на свете, лишь бы лишиться своего нынешнего опыта; снова стать чистым листом, и вот тогда я бы не стал приоткрывать дверь в эту бездну. Сейчас же поздно отнекиваться. Момент упущен. И теперь я могу…"},{"kind":"paragraph","text":"ДАША. ...только искать. Ворошить каждый сантиметр пространства в поисках излечения. Можно подумать, что речь моя…"},{"kind":"paragraph","text":"МИША. ...такая несуразная, несвязная. Но это ещё раз доказывает отсутствие фундамента под моими…"},{"kind":"paragraph","text":"ДАША. ...ногами."},{"kind":"paragraph","text":"Миша и Даша начинают сближаться к центру, не замечая друг друга. Молодые люди сталкиваются, начиная ошарашенно оглядываться, не в силах что-либо сказать. Она смущённо отворачивается в одну сторону, он — в другую (к залу). Сама неловкость порождает желание снова встретиться взглядами, чтобы только сказать:"},{"kind":"paragraph","text":"МИША. Простите."},{"kind":"paragraph","text":"ДАША. И вы меня…"},{"kind":"paragraph","text":"МИША. Не думал в такое время встретить на улице кого-то ещё, да в такой близости."},{"kind":"paragraph","text":"ДАША. Соглашусь."},{"kind":"paragraph","text":"МИША. Вы не сильно ушиблись?"},{"kind":"paragraph","text":"ДАША. Ничуть. А вы?"},{"kind":"paragraph","text":"МИША. Совсем нисколечко… Вы простите меня, но можно вопрос?"},{"kind":"paragraph","text":"ДАША. Задавайте."},{"kind":"paragraph","text":"МИША. А что вы делаете в такое время на улице?"},{"kind":"paragraph","text":"ДАША. Странно. Мне думалось, что ваш вопрос будет про моё имя."},{"kind":"paragraph","text":"МИША. М?"},{"kind":"paragraph","text":"ДАША. Что вы спросите, как меня зовут. Ваш вопрос."},{"kind":"paragraph","text":"МИША. Простите, просто имя — это не так важно для меня. Надеюсь, вас это не обижает, но с точки зрения информативности мой вопрос о том, что вы делаете в такое позднее время одна — куда интимнее и острее."},{"kind":"paragraph","text":"ДАША. А ведь действительно…Тогда как же вы меня окрестили в своей голове?"},{"kind":"paragraph","text":"МИША. Человек. Существо. Сознание. Первые три ассоциации."},{"kind":"paragraph","text":"ДАША. А вы тогда кто?"},{"kind":"paragraph","text":"МИША. Ровно то же самое, что и вы. Поэтому мне не столько интересно ваше имя, сколько мотивы."},{"kind":"paragraph","text":"ДАША. Я вышла из-за бессонницы… Да и на свежем воздухе думается лучше."},{"kind":"paragraph","text":"МИША. Как чудесно! Вы очень интересный человек."},{"kind":"paragraph","text":"ДАША. Вы уже делаете вывод по одному ответу?"},{"kind":"paragraph","text":"МИША. Безусловно!"},{"kind":"paragraph","text":"ДАША. Очень наивно с вашей стороны."},{"kind":"paragraph","text":"МИША. А вы много знаете людей, которые выходят ночью, только чтобы подумать? Потому как их мыслям тесно в бетонной коробке!"},{"kind":"paragraph","text":"ДАША. Тесно в бетонной коробке… Это вы хорошо сказали."},{"kind":"paragraph","text":"МИША. Спасибо на добром слове."},{"kind":"paragraph","text":"ДАША. Меня зовут…"},{"kind":"paragraph","text":"МИША. Не говорите! Прошу вас! Хотите, угадаю?"},{"kind":"paragraph","text":"ДАША. Попробуйте."},{"kind":"paragraph","text":"МИША. Вас зовут… дайте-ка подумать… Даша?"},{"kind":"paragraph","text":"ДАША. Как! Как вы…"},{"kind":"paragraph","text":"МИША. Очень просто. Вас назвали одним из распространённых имён. Как, впрочем, и меня. Поэтому имя ничего не значит, понимаете?"},{"kind":"paragraph","text":"ДАША. Вы Миша?"},{"kind":"paragraph","text":"МИША (смеётся). Вот вы и познали весь фокус. Не хотите пройтись со мной?"},{"kind":"paragraph","text":"ДАША. Почему бы и нет?"},{"kind":"paragraph","text":"МИША. Думать вслух в два мозга куда сподручнее, не правда ли?"},{"kind":"paragraph","text":"ДАША. Ещё не знаю, но не терпится проверить."},{"kind":"paragraph","text":"Миша и Даша неспешно идут плечом к плечу на зрителя. Поначалу молодые люди молчат, собираясь с мыслями. Привыкают друг к дружке. Тишина длится не более двух минут."},{"kind":"paragraph","text":"ДАША. Что же вы молчите?"},{"kind":"paragraph","text":"МИША. Простите?"},{"kind":"paragraph","text":"ДАША. Сказали, что будем думать вместе вслух, а сами…"},{"kind":"paragraph","text":"МИША. А я ведь действительно задумался про себя, по привычке."},{"kind":"paragraph","text":"ДАША. И о чём же вы задумались?"},{"kind":"paragraph","text":"МИША. Да всё о том же: что именно во мне определяет моё «Я»."},{"kind":"paragraph","text":"ДАША. И?"},{"kind":"paragraph","text":"МИША. И единственный ответ — это опыт."},{"kind":"paragraph","text":"ДАША. Тогда почему вы до сих пор…"},{"kind":"paragraph","text":"МИША. Может, будем обращаться на «ты»?"},{"kind":"paragraph","text":"ДАША. Почему ты до сих пор думаешь тогда об этом? Ответ ведь найден."},{"kind":"paragraph","text":"МИША. Всё равно как-то не верится… Своё «я» всегда казалось чем-то более сакральным и сложным, а тут получается, что человек в принципе не индивидуален. Сама подумай: если опыт получает один, то и аналогичный опыт получает другой. Всё различие колеблется в деталях: в достатке семьи, в полноценности таковой и в прочем, но структурно — человек не оригинален."},{"kind":"paragraph","text":"ДАША. И теперь? Разве для тебя это что-то меняет?"},{"kind":"paragraph","text":"МИША. Пока тяжело сказать, но что-то внутри немного поугасло, понимаешь? Всю жизнь мы чувствуем неосязаемый волшебный трепет. Каждый человек чувствует себя особенным. А потом, в какой-то момент, начинаешь понимать, что, как ни старайся, ты просто очередная копия. Ничем не лучше любого другого человека. Даже если этот человек — сумасшедший или убийца, или же, наоборот, праведник. Мы все одинаковы, и нет среди нас избранных, плохих, хороших. Сейчас мне кажется, что Бог не стал бы создавать таких бесполезных существ, чей главный инстинкт — размножение."},{"kind":"paragraph","text":"ДАША. Забавно. И ты прикинь, до чего дошёл этот инстинкт, раз так вплёлся в целую социальную эволюцию. Сколько этапов было преодолено, и все мы думали, что это прогресс; что и войны — сподвижник технического прогресса; что увеличение заводов — повод повышать демографию. Но если задуматься, то ведь внутренний червяк всё время давал нам незначительный повод совершить предначертанный грех. Как же теперь появиться новому человеку (и я сейчас не имею в виду физическое рождение); как родиться новой идее, когда все влиятельные круги, почти все творческие деятели, все нищие духом не видят изначального краха? Где же величие личности?"},{"kind":"paragraph","text":"МИША. Великая личность одинока. На то она и великая. И в продолжение темы: вся эта зависимость в бессмысленном продолжении рода — отвратительная черта. Но ещё хуже — пытаться освободить человека, лишив его иллюзий. Да… Понимаешь?! Нельзя освободить человека! Иначе какой хаос нас ждёт? Неприспособленные тушки просто не будут знать, куда деть себя! Что же делать им без иллюзий? А вот мы с тобой… Что даёт нам наша точка зрения?"},{"kind":"paragraph","text":"ДАША. Свободу!"},{"kind":"paragraph","text":"МИША. Но в чём она выражается? Ты разве не видишь, что мы сами себя заключаем в новые воздвигнутые стены…"},{"kind":"paragraph","text":"ДАША. Что ты несёшь?! Это ты думаешь о стенах — вот они и воздвигаются, а попробуй думать о бесконечно спокойном море — и ты увидишь свою безграничность."},{"kind":"paragraph","text":"МИША. От бесконечности можно сойти с ума. Знаешь, вслух действительно говорить правильнее. Это уже не просто внутренний диалог, а голос из пространства. Уже пытаешься воспринимать себя ушами, созданными для восприятия извне…"},{"kind":"paragraph","text":"ДАША. Ты перескакиваешь с одной темы на другую. Я уже ничего не понимаю."},{"kind":"paragraph","text":"МИША. Тут понимать особо нечего. Видишь ли… я сам давно не понимаю себя, а свой опыт — тем более… Какая же каша в голове."},{"kind":"paragraph","text":"ДАША. Миша…"},{"kind":"paragraph","text":"МИША. Какая боль! Как я растерзан всем этим дерьмом!"},{"kind":"paragraph","text":"ДАША. Не кричи… мне страшно."},{"kind":"paragraph","text":"МИША. Прости, но человек мне непонятен и страшен. Всё в моей голове смешалось… Это — хорошо. То — плохо."},{"kind":"paragraph","text":"Религии, войны, отношения, надо то, надо сё, пятое, десятое, найди себе друзей, найди девушку, найди работу, найди хобби, начни откладывать на бетонную коробку, переживай за пожилых родных, переживай за собственное здоровье, рак, инсульт, давление, эмоции, шизофрения, анализы крови, подозрительные прохожие, постоянно разлагающийся организм, социальные лестницы, недоверие, беспочвенная несправедливость людей, постоянное движение, отсутствие идеи, старость, боль, сожаление…"},{"kind":"paragraph","text":"ДАША. Мишенька…"},{"kind":"paragraph","text":"МИША. Прости меня за всё это, но я сам — не я вовсе. Просто бледная тень. И как тошно мне грузить тебя проблемами, когда у тебя есть свои. Зря мы повстречались."},{"kind":"paragraph","text":"ДАША. Да мы познакомились пять минут назад, я даже ещё не устала от тебя!"},{"kind":"paragraph","text":"МИША. Какая разница, если по итогу ты всё равно устанешь… И от меня, и от кого бы то ни было. Какая безумная человеческая трагедия — задумываться!"},{"kind":"paragraph","text":"ДАША. Так не думай больше!"},{"kind":"paragraph","text":"МИША. А это никак не получится, пока ещё есть силы дышать."},{"kind":"paragraph","text":"ДАША. В жизни непросто, Миш, но разве она того не стоит; разве все спектры удовольствия — не повод не вешать руки?"},{"kind":"paragraph","text":"МИША. Может и повод, но мне так скучно!"},{"kind":"paragraph","text":"ДАША. Так развеселись, столько всего чудесного вокруг!"},{"kind":"paragraph","text":"МИША. А мне хочется того, чего в этом «всего» нету. Знаешь, не бери в голову. Хорошо тебе погулять и подумать. Желаю тебе всего самого счастливого и светлого, что ты сможешь найти в себе."},{"kind":"paragraph","text":"ДАША. Но мы только познакомились."},{"kind":"paragraph","text":"МИША. А я уже устал, прости. Мне пора в свою кровать. Время притвориться собой."},{"kind":"paragraph","text":"ДАША. Время. Притвориться. Собой."},{"kind":"paragraph","text":"Даша растворяется в тени. Под Мишей появляется кровать. Перед зрителем снова оказываются бетонные стены дома и окна. Затем и Миша медленно исчезает под натиском темноты."},{"kind":"paragraph","text":"На сцену выходит человек в чёрном одеянии, начиная читать стихотворение:"},{"kind":"paragraph","text":"С улыбкой футлярной, перед зеркалом — стоит человек. Он видит себя по представлению; видит глаза, кожу, брови и нос, но не знает, как выглядит собственное нутро."},{"kind":"paragraph","text":"Человеку много показывают разных картинок: с сердцем, почками и скелетом, а ещё с морем на другой стороне планеты, которое останется таким же прозрачным и спокойным, но уже без нас."}]'::jsonb,
  '2023-12-31T12:00:00.000Z'
)
ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  author_id = EXCLUDED.author_id,
  cover_path = EXCLUDED.cover_path,
  cover_blur = EXCLUDED.cover_blur,
  cover_width = EXCLUDED.cover_width,
