  published_at = EXCLUDED.published_at;

INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd4-yagodki',
  'Ягодки',
  (SELECT id FROM "Authors" WHERE name = 'Кирилл Фирсов' ORDER BY id LIMIT 1),
  'mrd4/mrd4-yagodki.jpg',
  'data:image/jpeg;base64,',
  1186,
  1186,
  'Раскалённый, как чугунная сковорода, асфальт искажал воздух, создавая волнистые аномалии. Безветренное, бездождевое лето убивало своей сухостью даже кузнечиков, поэтому слышно было не их треск, а треск высоковольтных лин',
  '[{"kind":"image","path":"mrd4/mrd4-yagodki.jpg","caption":null},{"kind":"paragraph","text":"Раскалённый, как чугунная сковорода, асфальт искажал воздух, создавая волнистые аномалии. Безветренное, бездождевое лето убивало своей сухостью даже кузнечиков, поэтому слышно было не их треск, а треск высоковольтных линий, тянущихся вдоль дороги. Очкастый ехал со скоростью сто сорок километров в час, и для старенькой «девятки» это было уже очень много. Машина тряслась, её мотало во все стороны, а каждая выбоина или скол подымали «девятку» ввысь, она опускалась с дребезгом и продолжала разрезать жаркий воздух."},{"kind":"paragraph","text":"Очкастый часто посматривал в зеркало заднего вида. За его узкими прямоугольными очками скрывались сосредоточенные глаза беркута, осматривающего свои владения. Сзади никого не было, а вот впереди… Очкастый снизил скорость и полез в бардачок. Бардачок открылся с диким треском, водитель достал что-то завёрнутое в чёрный полиэтиленовый пакет и положил в карман своей спортивной олимпийки. Очки сползли от телодвижений к кончику носа, но Очкастый указательным пальцем правой руки медленно поместил их на переносицу. Глаза водителя нацелились на далёкую фигуру человека, стоящего у дороги. Очки ярко забликовали."},{"kind":"paragraph","text":"На горячем щебне рядом с дорогой стоял мужичонка, довольно низкий, но коренастый. Голову его украшала красная панама. Панама поднимал большой палец вверх на вытянутой руке, совсем как какой-нибудь Калигула на гладиаторских играх. Только Панама ловил попутку, а не даровал жизнь. Улов сегодня был скуден. Никто, кроме старой «девятки», около Панамы не остановился, не то что вчера или позавчера. Но он был рад и такому."},{"kind":"paragraph","text":"— Подвезти, турист? — немного саркастично произнёс Очкастый."},{"kind":"paragraph","text":"— Очень даже можно, а вы куда? — подбегая к машине, крикнул Панама."},{"kind":"paragraph","text":"— Прямо, — открывая пассажирскую дверь изнутри, отрезал водитель."},{"kind":"paragraph","text":"— Хорошо, очень хорошо… — Панама посмотрел по сторонам с прищуром ящера."},{"kind":"paragraph","text":"Пыль вырвалась из-под колёс и осела на дороге в виде серого песка. Девятка полетела дальше, но теперь с пассажиром. Неловкое молчание царило совсем недолго, прервал его улыбчивый и кривозубый Панама:"},{"kind":"paragraph","text":"— Откуда будете?"},{"kind":"paragraph","text":"— С Ленинграда, — улыбнулся по-монализовски Очкастый, — а вы?"},{"kind":"paragraph","text":"— Да я с глубинки, с Ивановской области, Тейково. А куда едете — домой, видимо? — Панама оценивающе осмотрел салон."},{"kind":"paragraph","text":"— Наш дом там, где мы, а свобода перемещения у нас закреплена в Конституции, — насупился Очкастый, прижав голову книзу, выдавливая складочку второго подбородка."},{"kind":"paragraph","text":"— Хорошо сказано, я тоже не сижу на месте, движение — жизнь! — манерно прочитал Панама."},{"kind":"paragraph","text":"— В смерти — жизнь. Эдгар Аллан По, читали? — не обращая внимания на пассажира, спросил Очкастый. Он тщательно высматривал поворот с основной дороги, но дорога вилась как змея без каких-либо ответвлений. При этом, как аванпосты, стояли через каждые пятьсот метров придорожные грибники и ягодники. Кто-то продавал лисички, белые, опята, кто-то — малину и чернику. Все меланхолично вглядывались в приближающуюся машину, ожидая удачную сделку."},{"kind":"paragraph","text":"— Не, не люблю читать, там всё ненастоящее, плоское, выдумка. Люблю видеть, трогать, нюхать… — Панама посмотрел на водителя и мысленно облизал его с ног до головы, — ощущать вкус."},{"kind":"paragraph","text":"— Вкус не у всех есть, вкус — это труд, его нужно вытачивать, давать огранку, как хорошему бриллианту. Раньше вкус ценился: к последнему маргиналу подойди — так он эстет или хотя бы имел свой стиль, свою культуру мышления, а сейчас что? — Очкастый скривил губы. — Тупость, показуха и безвкусица."},{"kind":"paragraph","text":"— Ретроградство — порок стареющего рассудка: всё новое плохо, всё хорошее уже прошло, а через поколение новое плохое станет хорошим старым и дальше, и дальше, и дальше. Раньше, сейчас, потом — как можно сравнивать? Такие разные ощущения: то одни лучше, то другие, не знаешь, когда их испытаешь, — Панама потёр кончиками пальцев засаленную каёмку своей красной панамки, — на каком моменте жизни."},{"kind":"paragraph","text":"Очкастый резко нажал по тормозам и сбросил скорость вдвое. От такого манёвра оба подпрыгнули на сиденьях. Впереди, через сотню метров, был заворот грунтовой дороги. Дорога вела в небольшой лесок, где, видимо, и собирали грибы да ягоды стоящие у обочины торговцы. Но Очкастый очень надеялся на безлюдность близлежащего лесочка."},{"kind":"paragraph","text":"— Чего это так мы сворачиваем? Сказали же, прямо едем? — игриво заметил Панама."},{"kind":"paragraph","text":"— Здесь короче будет. Дальше дорога в крюк идёт через посёлки, а через просёлочную можно срезать и полчаса сэкономить, — взгляд Очкастого был прикован к зеркалу заднего вида."},{"kind":"paragraph","text":"С замиранием сердца Очкастый следил за обстановкой вокруг. На его счастье, вокруг царила полнейшая тишина. Ни людей, ни машин, ни грибников и ягодников, которых на этом участке дороги было уж слишком много. Панама при этом стал зажимать губы так, как люди обычно сдерживают свой смех. Он аккуратно потирал что-то твёрдое, торчащее из-за ремня шорт. Это «что-то» немного торчало из-под футболки и было похоже то ли на спрятанный карандаш, то ли на…"},{"kind":"paragraph","text":"— Красиво здесь, а? — улыбчиво заметил Панама."},{"kind":"paragraph","text":"— Кому как, кому как. Мне нравится лес не за красоту, не за птичек и не за шишки. Знаете, за что мне нравится лес? — прищурив глаза, спросил Очкастый."},{"kind":"paragraph","text":"— За что же? — не сбрасывая улыбки с лица, продолжал Панама."},{"kind":"paragraph","text":"— Тихо… — Очкастый свернул с просёлочной дороги в сторону высоких сосен, — можно уйти в лес, и там никто не осудит, там нет правил, законов, предписаний. Антоновщина в лес уходила, потому что здесь свобода."},{"kind":"paragraph","text":"— А мне нравится город: в городе интереснее, всё живое такое, бьёт ключом, пульсирует, — Панама нежно погладил левой рукой кисть правой руки, подушечками пальцев трепетно огибая каждую выступающую венку."},{"kind":"paragraph","text":"— Город — злая сила, как выразился один персонаж фильма."},{"kind":"paragraph","text":"Отъехав от дороги полкилометра, Очкастый полностью остановился и заглушил мотор."},{"kind":"paragraph","text":"— Я вас покину ненадолго, отойду по нужде? — Очкастый посмотрел косо на пассажира и открыл дверь."},{"kind":"paragraph","text":"— Да-да, конечно, — улыбчиво ответил Панама."},{"kind":"paragraph","text":"Выходя из машины, Очкастый быстро определил самую большую сосну и встал за ней так, чтобы пассажир его не видел. Расстегнув ширинку, Очкастый задумчиво помочился под сосну, а потом протёр руки маленькой влажной салфеточкой, которая лежала во внутреннем кармане олимпийки. После того, как руки стали чисты, Очкастый достал из кармана чёрный свёрток, развернул его и вытащил два колечка, соединённые шершавой витой проволокой. Оба колечка Очкастый надел на указательный палец, на него же надел кольцо с ключом от машины, дабы замаскировать предыдущие, а размотавшуюся проволоку засунул в рукав, после чего прогнал в голове сценарий: «Подхожу к колесу, пинаю, ругаюсь, стучу по стеклу, прошу выйти, прошу наклониться, накидываю пилу»."},{"kind":"paragraph","text":"— Ну, с Богом."},{"kind":"paragraph","text":"Очкастый вышел из-за сосны и резко потупил взгляд. Машина была пуста, вокруг никого не было. Он покрутился, повертел головой, но ничего не нашёл. Тогда Очкастый нацелил взгляд на днище автомобиля и ухмыльнулся. Около колеса торчал кусочек ярко-красной панамки. Очкастый медленно подошёл к колесу, наклоняясь к панаме."},{"kind":"paragraph","text":"— Гражданин, вы чего это удумали, там же грязно…"},{"kind":"paragraph","text":"Под машиной лежала только панама, без человека. Холодок пополз по лысенькой макушке Очкастого. От хрустящего шороха сзади он дёрнулся и резко обернулся. Блеск игольной точки отразился в стекле очков. Очкастый отпрыгнул от машины, а Панама (только уже без панамы) с чем-то острым в руках влетел в заднее крыло «девятки»."},{"kind":"paragraph","text":"— Ушёл, ушёл, ишь какой, Ванька-встанька! — Панама засмеялся и обозлился одновременно."},{"kind":"paragraph","text":"— А ну стоять, сволочь! — Очкастый, как фокусник, вытащил из ботинка маленький складной ножичек. — Только сделай шаг, как свинью прирежу."},{"kind":"paragraph","text":"— Ой, ой, ой, какой ферзь, я сразу понял, кто ты таков, я делиться рыбой в этом озере не собираюсь, — сжимая заточенную отвёртку, с усладой щебетал Панама."},{"kind":"paragraph","text":"— И что, лучше будет погрызть друг друга? Я тебе брюхо вспорю, а ты меня проткнёшь своей финкой. Ты будешь здесь валяться, а я не успею до больницы доехать — до неё триста километров, истеку кровью, закрою глаза и слечу с дороги прямо в дерево. Может, договориться лучше?"},{"kind":"paragraph","text":"Оба стояли, как тигры перед броском: примерялись, прикидывали, прицеливались, немножко потрясывались от излишнего напряжения."},{"kind":"paragraph","text":"— А ты думаешь, меня завалишь? Первый? А не я тебя? — Панама немного задребезжал."},{"kind":"paragraph","text":"— Да, — ответ Очкастого пронёсся по лесу, как звон молотка, ударившего наковальню."},{"kind":"paragraph","text":"Панама задумался. Ему не хотелось лежать в лесу, лес был вынужденной средой его охоты. Он любил город, но после недавних инцидентов ему пришлось уйти на межгородские трассы. Очкастый же злился на себя за то, что посвятил всё внимание обстановке и совсем не проанализировал «клиента». Обоим нужен был компромисс, хотя бы для того, чтобы выжить, а потом можно и разъехаться восвояси."},{"kind":"paragraph","text":"— Ну что, водолаз, довезёшь до людей-то хоть? — Панама стал медленно тянуться к своему головному убору."},{"kind":"paragraph","text":"— Довезу, даю слово, — Очкастый медленно стал отходить к водительской двери."},{"kind":"paragraph","text":"Оба очень осторожно сели, выставляя оружие в сторону врага. Смотрели при этом чётко в зрачки друг друга. Ветерок подул по сухой лесной подстилке, и та заершилась сухими веточками, иголочками и листиками. На Панаму был нацелен нож, самодельное шило было нацелено на Очкастого. Пальцы дуэлянтов сжимали свои шпаги с таким усилием, что, казалось, лопнут."},{"kind":"paragraph","text":"— Ну что, едем? — улыбчиво предложил Панама."},{"kind":"paragraph","text":"— Едем, только финки бросим, давай на раз…"},{"kind":"paragraph","text":"— Два, — продолжил Панама, не дожидаясь своего оппонента."},{"kind":"paragraph","text":"Капельки пота стекали по лбу каждого из них, но отнюдь не от жары. Взгляды настолько приклеились друг к другу, что всё, кроме лица напротив, в поле зрения стало серым, как видеошум в телевизоре."},{"kind":"paragraph","text":"— Три, — сказал Очкастый и выбросил нож."},{"kind":"paragraph","text":"Панама не стал выбрасывать отвёртку, но быстро засунул её обратно за ремень. Очкастый завёл «девятку», и они поехали обратно по тому же пути. До дороги ехали молча, как поссорившиеся супруги, но как только выехали на асфальт, молчание опять прервал Панама."},{"kind":"paragraph","text":"— И долго ты вот так вот? — улыбки уже не было."},{"kind":"paragraph","text":"— Двадцать с небольшим, — недовольно ответил Очкастый."},{"kind":"paragraph","text":"— Ого, я-то всего ничего, и уже портреты везде висят меня красивого. Это ты прям старшо́й, получается, у тебя учиться, учиться и ещё раз учиться надо, — по интонации Панамы не было понятно, шутит он или прощупывает почву на продолжение разговора."},{"kind":"paragraph","text":"— Чем ты аккуратнее, тем дольше прозанимаешься любимым делом. А главное знаете что? — по-учительски спросил Очкастый."},{"kind":"paragraph","text":"— Что же? — по-детски взглянул на него Панама."},{"kind":"paragraph","text":"— Всегда быть на людях, иметь много друзей, причём в органах и среди крупных воротил. И когда ты исчезаешь из светского болота, никто никогда не узнает, чем ты занимаешься на самом деле. Это не каждому дано, отнюдь. Я и сам в органах работал немного. Там я много выводов сделал. Прежде всего о том, как полезны связи и как можно скрывать ото всех настоящую жизнь."},{"kind":"paragraph","text":"— И что это даёт? Зачем столько сил тратить на ненастоящую жизнь? — немного брезгливо подметил Панама."},{"kind":"paragraph","text":"— Это даёт всё, абсолютно всё. Власть, деньги, удовольствия. Вы даже не знаете, кто я, откуда, а я могу узнать о вас всё, лишь только попросив нужных людей, я могу вершить вашу судьбу, — последняя фраза звучала очень обыденно для Очкастого."},{"kind":"paragraph","text":"— А вот с этим ты что сделаешь, вершитель судеб?"},{"kind":"paragraph","text":"Панама быстро вытащил из штанов шило и приставил к кадыку Очкастого. Кривые зубы заскрипели, а пальцы побелели от натуги."},{"kind":"paragraph","text":"— Я прямо сейчас могу решить твою судьбу, но у меня нет ни знакомых, ни связей, у меня есть только отвёртка, заточенная напильником, — Панама рассмеялся."},{"kind":"paragraph","text":"Несмотря на невыгодное положение, Очкастый даже не вздрогнул — он продолжал следить за дорогой и что-то высматривать."},{"kind":"paragraph","text":"— Мой человек едет позади нас, между нами около километра. В машине установлен трекер, поэтому её легко отследить. На мне тоже трекер, на всякий случай. Если со мной что-то случится, тебя быстро найдут, и ты не умрёшь сразу, я могу гарантировать, — голос Очкастого с приставленной к шее отвёрткой звучал даже спокойнее, чем без неё."},{"kind":"paragraph","text":"— Ага, конечно, человек у него! Ты себя-то видел: на корыте разъезжаешь, одет как физрук мой покойный, Иван Ефимыч. Ты мне мозги не парь, умник хуев! — Панама надавил шилом на кадык Очкастого, оставив красную точку на коже."},{"kind":"paragraph","text":"Очкастый нажал на одну из кнопок магнитолы и в первый раз посмотрел на Панаму. Из колонок зашипели радиопомехи."},{"kind":"paragraph","text":"— Миша, как обстановка?"},{"kind":"paragraph","text":"— Всё хорошо, Матвей Александрович, чисто, — хрипло донеслось из колонок."},{"kind":"paragraph","text":"— Спасибо, Миш, до связи."},{"kind":"paragraph","text":"— Охуеть, — на лице Панамы опять расплылась широкая улыбка. — Так значит, это правда, что ли?"},{"kind":"paragraph","text":"— Что ли правда, значит."},{"kind":"paragraph","text":"Панама смущённо опустил голову и убрал шило за ремень. Наступило задумчивое молчание. Прерывистая полоса разметки быстро исчезала под капотом «девятки»."},{"kind":"paragraph","text":"— А имя я всё-таки твоё узнал, получается, Матвей Александрович, — косо взглянул Панама на Очкастого, не поворачивая головы."},{"kind":"paragraph","text":"— А с чего ты решил, что меня на самом деле так зовут? — улыбнулся Очкастый."},{"kind":"paragraph","text":"Опять наступило молчание. Летнее солнце сверкало сквозь макушки высоких деревьев, оставляя в глазах мутные пятна."},{"kind":"paragraph","text":"— А чего ты тогда на развалюхе, и одет так, да и вообще здесь, в жопе мира? Ты, наверное, можешь на любого пальцем тыкнуть, и тебе его на блюдечке принесут."},{"kind":"paragraph","text":"— Аккуратность, я уже говорил, а ещё неожиданность. Никто не ожидает меня увидеть здесь, в таком виде. Вчера я остановился в бывшей гостинице «Москва», и все думают, что я до сих пор там. А я здесь. Да и если хочешь сделать что-то хорошо, сделай это сам."},{"kind":"paragraph","text":"— И зачем ты мне всё это тогда рассказываешь? Аккуратный? Думаешь, я идиот совсем? Сейчас подъедут твои головорезы — я и моргнуть не успею, как меня завалят! — Панама гневно прикрикнул."},{"kind":"paragraph","text":"— Да, так бы и было, но мне хочется предложить тебе работу. Ты меня не боишься и мало чего боишься в принципе, да и руки запачкать не против, как вижу. Мне такие парни нужны — крепкие, смелые…"},{"kind":"paragraph","text":"— И зачем мне это? Я сам по себе всю жизнь. Стать цепным псом не желаю."},{"kind":"paragraph","text":"— Ну тут два варианта. Либо будешь работать на меня, либо… — Очкастый на секунду скрутил губы уточкой и прищурился. — С такой информацией долго не живут люди, а жить тебе, как вижу, очень нравится, так что тут здравый расчёт. Делай выбор."},{"kind":"paragraph","text":"Панама отвернулся в окно и нахмурился. Очкастый продолжал пристально смотреть вдаль."},{"kind":"paragraph","text":"— И что мне надо будет делать, если соглашусь? — тихо спросил Панама."},{"kind":"paragraph","text":"— В основном ждать. Квартиру я тебе предоставлю, зарплату два раза в месяц в руки будет привозить курьер, еду тоже, в магазины больше ходить не будешь и вообще никуда днём ходить, желательно. Когда появится дело, за тобой приедут, а после отвезут обратно."},{"kind":"paragraph","text":"— Я так не могу, не могу без рыбалки, я охотник по натуре, свободный, как наши предки кроманьонцы, — Панама улыбнулся."},{"kind":"paragraph","text":"— Буду брать тебя с собой на рыбалку, иногда помощник не помешает, — Очкастый со скрипом сжал руль."},{"kind":"paragraph","text":"— А если ты мне прямо сейчас в уши ссышь? Доедем куда-нибудь, и на следующий день найдут меня зарезанным в сортире?"},{"kind":"paragraph","text":"— Не найдут, если я всё же решу с тобой разобраться. Но я не буду. Мне всегда нужны люди, которые будут делать ту работу, за которую остальные не возьмутся. Поэтому предлагаю тебе сотрудничать. Ну, или ты знаешь, в противном случае, что будет, так что, по сути, у тебя один верный вариант."},{"kind":"paragraph","text":"В течение нескольких минут Панама обдумывал предложение своего странного спутника. Взвешивал, рассуждал, анализировал внутри своего сознания. Но ответ дать так и не успел, Очкастый прервал его мыслительный процесс."},{"kind":"paragraph","text":"— Давай-ка поохотимся вместе в знак начала плодотворного сотрудничества."},{"kind":"paragraph","text":"— На кого? — в недоумении спросил Панама."},{"kind":"paragraph","text":"— Впереди, видишь, ягодами сидит торгует."},{"kind":"paragraph","text":"Впереди и правда сидела одинокая бабушка и торговала ягодами. Панама скорчил брезгливую гримасу."},{"kind":"paragraph","text":"— Что такое? — вежливо спросил Очкастый."},{"kind":"paragraph","text":"— Старость, фу, от них воняет."},{"kind":"paragraph","text":"Машина остановилась прямо около ветхой улыбающейся бабушки. На голове её был повязан красный ситцевый платок, а весь остальной наряд был как у дымковской игрушки."},{"kind":"paragraph","text":"— Почём ягодки, бабуль? — задорно окликнул старушку Панама, выходя из машины."},{"kind":"paragraph","text":"— Ой, разные, сынок. Малина есть, черника, смородина красная, чёрная, тебе что больше нравится? — бабушка посмотрела на Панаму добрыми лучезарными очами."},{"kind":"paragraph","text":"— Черника нравится, только у тебя тут сколько?"},{"kind":"paragraph","text":"К бабушке подошёл и Очкастый."},{"kind":"paragraph","text":"— Вот пять стаканчиков, значит, по триста каждый, — скромно ответила старушка."},{"kind":"paragraph","text":"— Маловато, а больше нет? Нам надо на всю семью ягод, а семья-то у нас ого-го какая, да, Матвей Саныч? — Панама похлопал Очкастого по плечу."},{"kind":"paragraph","text":"— Давайте, матушка, вы нам всё по пятьсот отдадите и отведёте нас на ягодное место? Тут наверняка недалеко, а мы вам сверху ещё пять тысяч накинем за услугу, — Очкастый достал толстенный кошель и отсчитал нужное количество купюр."},{"kind":"paragraph","text":"— Ты что, сынок, ты что, я и не возьму, и не пойду никуда, ноги уже не ходят, эти-то еле собрала, — щёки бабушки стеснительно зарумянились."},{"kind":"paragraph","text":"— Не дойдём мы сами, бабуль, сделай милость, городские, заблудимся, а мы уж отблагодарим, век не забудем. Старость мы уважаем, — Панама задорно улыбнулся, обнажая весь верхний ряд своих кривых зубов."},{"kind":"paragraph","text":"— А остальные-то ягоды, милки, как же я оставлю? — бабушка заметалась от растерянности."},{"kind":"paragraph","text":"— Всё берём, матушка, пригодятся, — спокойно ответил Очкастый и протянул веер из банкнот."},{"kind":"paragraph","text":"Бабушка стыдливо взяла деньги, покланялась в пол «сынкам», и вместе они отправились в сторону леса. Панама с бабушкой отошли вперёд и разговорились о сортах яблок и груш, а конкретно — об их вкусовых преимуществах."},{"kind":"paragraph","text":"— «Богатырь» всё-таки не нравится мне, кислый больно, — Панама резко замолчал. — Хотя если посолить и с коньяком, то очень даже ничего, — подытожил он разговор о яблоках."},{"kind":"paragraph","text":"Очкастый тем временем смотрел по сторонам и проворачивал в голове план действий: «Выходим в лес, этот дурак душит бабку, достаю нож, удар, звоню Мише». После того, как он тщательно провертел всё ещё несколько раз, подошёл к Панаме сзади и незаметно вложил в его руку удавку с двумя кольцами, которой он хотел недавно придушить самого Панаму. Панама, не оборачиваясь, кивнул."},{"kind":"paragraph","text":"— Пришли, сыночки, вот, смотрите: как камушки-самоцветы, всё синёхонькое от ягод, — бабушка широко раскинула правой рукой."},{"kind":"paragraph","text":"— Где, бабуль? Не понял что-то, а ну покажи, — наигранно произнёс Панама."},{"kind":"paragraph","text":"— Да вот же."},{"kind":"paragraph","text":"Бабушка наклонилась к ягодам, чтобы сорвать парочку сынкам на угощение. Один сынок уже раскрутил удавку и пристроился к старческой шее, медленно примеряясь и оценивая лучшую позицию для удушения."},{"kind":"paragraph","text":"«Хрясь», — прозвучал хрящевой треск. Топор вонзился в голову Панамы прямо посередине той самой панамы. Из-под головного убора на топорное лицо хлынул водопад крови. Бабушка настолько быстро достала из кустов черники топор и вонзила его Панаме в череп, что Очкастый оцепенел от неожиданности. На его счастье, ступор быстро прошёл, и он достал из рукава ножичек."},{"kind":"paragraph","text":"«Бдыщ», — левое стекло очков треснуло, а из глаза хлынула струя. Бабушка стояла среди черники и держала в руке дымящийся маузер, который достала из бюстгальтера со скоростью мангуста."},{"kind":"paragraph","text":"— Нехорошо, сынки, бабушку наёбывать, — старушка подошла к Панаме, упёрлась в него ногой и смачно выдернула топор из его башки. — Ну ничего, вы бабушке ещё послужите."},{"kind":"paragraph","text":"Старуха наклонилась к каждому из трупов, приоткрыла рты и засыпала в них немного черники. После чего обтёрла топор, кинула его обратно в кустики, а маузер спрятала в прежнем месте."},{"kind":"paragraph","text":"Михаил нервно постукивал по рулю старенького «мерина», панически всматриваясь в дорогу. Вдруг его взгляд остановился на силуэтах двух грибников-ягодников, стоявших у дороги вдалеке. Прибавив газу, Миша доехал до мужиков и выбежал из машины."},{"kind":"paragraph","text":"— Матвей Александрович, ну вы и напугали, я ж вас обыскался, смотрю — машина пустая у дороги, от вас сигнал пропал, я уж думал, всё, не найду, — Миша по-матерински погладил начальника по плечу."},{"kind":"paragraph","text":"— Мужик, ты чё, из этих, что ли? Ягоды брать будешь? — спросил угрожающе Панама."},{"kind":"paragraph","text":"— Матвей Александрович, всё нормально? — не обращая внимания на Панаму, заверещал охранник."},{"kind":"paragraph","text":"— Мужчина, вам сказали: ягоды берите или уезжайте, черника по триста, земляника по пятьсот, — Очкастый с одним разбитым стеклом недовольно буркнул на Михаила."},{"kind":"paragraph","text":"— Матвей Александрович, — охранник прищурился и немного успокоился. — Vincere aut mori[1], — на ломаной латыни произнёс он, ожидая ответного слова."},{"kind":"paragraph","text":"— Дурак, что ли? Ягоды будешь брать? — совсем раздражённо спросил Очкастый."},{"kind":"paragraph","text":"— Саш, подъедь, пожалуйста, прямо сейчас, я не понимаю, что происходит, — прогундел в рацию Михаил и быстро отошёл к машине."},{"kind":"paragraph","text":"Панама и Очкастый стояли около стаканчиков с ягодами и, недоумевая, смотрели на убегающего охранника."},{"kind":"paragraph","text":"— А черника в этом году хороша, — подметил Панама, залезая рукой под свой головной убор, чтобы расчесать свежий шрам от топора."},{"kind":"paragraph","text":"— Надо ещё сегодня насобирать, — потирая левый глаз, утвердительно добавил Очкастый."}]'::jsonb,
  '2023-12-31T12:00:00.000Z'
)
