INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd4-sigareta-dlinoyu-v-zhizn',
  'Сигарета длиною в жизнь',
  (SELECT id FROM "Authors" WHERE name = 'Оганес Мартиросян' ORDER BY id LIMIT 1),
  'mrd4/mrd4-sigareta-dlinoyu-v-zhizn.jpg',
  'data:image/jpeg;base64,',
  1586,
  915,
  '«Не взлетишь, зато не упадёшь» — по этому принципу живут многие, являясь антонимами Гагарина. Так и пребывают в миру.',
  '[{"kind":"image","path":"mrd4/mrd4-sigareta-dlinoyu-v-zhizn.jpg","caption":null},{"kind":"paragraph","text":"«Не взлетишь, зато не упадёшь» — по этому принципу живут многие, являясь антонимами Гагарина. Так и пребывают в миру."},{"kind":"paragraph","text":"— Привет, как тебя зовут?"},{"kind":"paragraph","text":"— Антоним Гагарина. А тебя?"},{"kind":"paragraph","text":"— Тоже так."},{"kind":"paragraph","text":"— Женимся?"},{"kind":"paragraph","text":"— Ну конечно."},{"kind":"paragraph","text":"Стоят на углу, переминаются с ноги на ногу, после чего набрасываются друг на друга, срывают одежду и занимаются с нею сексом: имеют куртку, шапку, носки. И мозги, которые тоже снимают и надевают."},{"kind":"paragraph","text":"Кафе. Он и она пьют вино, наливая его в стакан, пока она не говорит:"},{"kind":"paragraph","text":"— Я не буду пить из бутылки: она — эрегированный член."},{"kind":"paragraph","text":"— Так наоборот надо."},{"kind":"paragraph","text":"— Закажи пакет молока. Он — антисекс."},{"kind":"paragraph","text":"— Не лучше упаковку «Каберне» или «Шато» — среднее между ними?"},{"kind":"paragraph","text":"— Ладно, но — нет."},{"kind":"paragraph","text":"Её рука хватает бутылку и разбивает её об его голову."},{"kind":"paragraph","text":"— Только что вы совершили гомосексуальный акт."},{"kind":"paragraph","text":"Бабушка находится в очереди за хлебом, сзади встаёт кавказец, женщина просит пощадить её, потому задирает платье, спускает трусы и показывает армянину или грузину свою чёрную дыру, в которую стекают новорождённые дети, чтобы из старухи попасть на Венеру и Марс."},{"kind":"paragraph","text":"Библиотекарь долго смотрит на девочку и спрашивает её:"},{"kind":"paragraph","text":"— Вам песни Пресли или Моррисона?"},{"kind":"paragraph","text":"— Учитель задал Толстого."},{"kind":"paragraph","text":"— Значит, Джаггера?"},{"kind":"paragraph","text":"— Да, можно его."},{"kind":"paragraph","text":"— Сосиски, колбасу, паштет будете брать?"},{"kind":"paragraph","text":"— Я голодна."},{"kind":"paragraph","text":"— Хорошо."},{"kind":"paragraph","text":"Посетительница садится за стол, включает музыку и ест, покачивая головой, плоской и покоящейся на трёх китах её тела, притом что пара из них совокупляется."},{"kind":"paragraph","text":"Есенин танцует на улице и орёт сногсшибательные тексты, читает рэп, пьёт текилу, возможно, виски, ещё вероятней его, но Новый год, счастливые лица, дети, ёлки, фейерверки, салаты, шампанское, шимпанзе любви, гориллы желания, макаки бесед и тела Есениных, висящие на каждом фонаре, покачивающие светом голов, читающих «Не жалею, не зову, не плачу…», так как основное занятие трупов — чтение про себя или вслух."},{"kind":"paragraph","text":"И ещё: кассир пробивает на кассе водку, смотрит на старика, которому лет девяносто, и спрашивает его:"},{"kind":"paragraph","text":"— Вам есть восемнадцать лет?"},{"kind":"paragraph","text":"— Да."},{"kind":"paragraph","text":"— А сто лет?"},{"kind":"paragraph","text":"— Пока что нет."},{"kind":"paragraph","text":"— Вот как стукнет, тогда и приходите ко мне."},{"kind":"paragraph","text":"— Домой?"},{"kind":"paragraph","text":"— Можно и туда. Ведь каждая женщина анализирует своего мужчину, разбирает его и удовлетворяет сумму подмышек — влагалище — при помощи руки, ноги, головы, шеи, члена."},{"kind":"paragraph","text":"Далее. Велосипедист заправляет шины двумя змеями, едет, но по ходу движения им хочется соития, они выползают и занимаются случкой на профессиональном уровне, потому что велосипед — это скелет первого человека."},{"kind":"paragraph","text":"— Купи мне булочку."},{"kind":"paragraph","text":"— У меня нет денег."},{"kind":"paragraph","text":"— Убей кого-нибудь и забери его деньги."},{"kind":"paragraph","text":"— Меня посадят лет на двадцать."},{"kind":"paragraph","text":"— Я подожду."},{"kind":"paragraph","text":"— Сколько ватрушка стоит твоя?"},{"kind":"paragraph","text":"— Рублей тридцать."},{"kind":"paragraph","text":"— Ну, хорошо."},{"kind":"paragraph","text":"Он совершает убийство, садится на восемнадцать лет, выходит, возвращается к месту встречи и дарит своей подруге поесть за двадцать девять рублей, они счастливо обнимаются и уходят в обнимку. Это и есть любовь."},{"kind":"paragraph","text":"Баллард взбирается на высотку, стоит на крыше, пьёт бурбон, машет руками и изображает сумасшедшего. Достаёт «Выставку жестокости», делает из неё домик и заселяется в него, говоря:"},{"kind":"paragraph","text":"— Все писатели повесились на тканевых закладках своих собственных книг, которые потолок, скрывающий и не дающий ни капли звёзд, пока под ним горит голова."},{"kind":"paragraph","text":"Ему отвечает эхо:"},{"kind":"paragraph","text":"— Чтобы не было потолка, не надо писать книг."},{"kind":"paragraph","text":"— Но без него нет звёзд. Тюрьма создана для того, чтобы была свобода."},{"kind":"paragraph","text":"— Не поспоришь."},{"kind":"paragraph","text":"— Ну вот."},{"kind":"paragraph","text":"Баллард перелистывает страницу и исчезает в ней."},{"kind":"paragraph","text":"Ты врубаешь телевизор, он показывает голову Босха, и та говорит:"},{"kind":"paragraph","text":"— Привет."},{"kind":"paragraph","text":"Ты отвечаешь:"},{"kind":"paragraph","text":"— Ну да."},{"kind":"paragraph","text":"— Трудно ответить тем же?"},{"kind":"paragraph","text":"— Привет."},{"kind":"paragraph","text":"— Это хорошо. Смотришь меня?"},{"kind":"paragraph","text":"— Вижу и слушаю."},{"kind":"paragraph","text":"— Можешь пожать мне руку."},{"kind":"paragraph","text":"— Я не хочу."},{"kind":"paragraph","text":"— Тогда я включу свои тучи и солнце."},{"kind":"paragraph","text":"— Они есть одно."},{"kind":"paragraph","text":"— Да, облако не скрывает светило, но подчёркивает его красоту, как одежда — тело."},{"kind":"paragraph","text":"— Усиливает её."},{"kind":"paragraph","text":"— Конечно."},{"kind":"paragraph","text":"Голова Босха начинает грызть семечки, пить пиво и материться, после чего губами удовлетворяет нечто, похожее на вагину с торчащим из неё цветком и ползающим по ней шмелём."},{"kind":"paragraph","text":"Каждого мужчину зовут Мужчина, где Билл, Хасан и Иван — псевдонимы его."},{"kind":"paragraph","text":"Женщина курит сигарету — член — вагиной и выдыхает облако, в котором и на котором плывёт её ребёнок Христос."},{"kind":"paragraph","text":"Самые глупые и неправильные люди — те, что умирают. Вот ты скончался, ну и что? Тебя за это отчитывает мама:"},{"kind":"paragraph","text":"— Дурачок, зачем ты умер? Теперь не сможешь есть и гулять."},{"kind":"paragraph","text":"— Мама, я больше не буду."},{"kind":"paragraph","text":"— Не будет он… Ну хорошо. Но чтоб в следующий раз такого не было!"},{"kind":"paragraph","text":"— Идёт!"},{"kind":"paragraph","text":"Или в школе над тобой все смеются и тычут пальцами:"},{"kind":"paragraph","text":"— Он умер, ха-ха!"},{"kind":"paragraph","text":"— Ну и что? — отвечаешь ты."},{"kind":"paragraph","text":"— Что? Тебя похоронят, и твоё тело сожрут черви."},{"kind":"paragraph","text":"— Пускай, мне плевать."},{"kind":"paragraph","text":"— Дурак ты."},{"kind":"paragraph","text":"— Ну что ж."},{"kind":"paragraph","text":"Ты уходишь ото всех и долго гуляешь по городу, наслаждаясь тем, что тебя нет, и тебе в первый раз хорошо. Хоть и глупо, как сказано выше."},{"kind":"paragraph","text":"Со временем может выясниться, что Сизиф закатывал на гору — своё тело — камень — свою голову, отрезанную чеченцами в ходе Первой чеченской войны."},{"kind":"paragraph","text":"Солнце — пуля в затылок, звёзды — расстрел у стены. Первое — мрак, остальное — свет. Выбирай."},{"kind":"paragraph","text":"На улице вдруг все замирают, раздеваются догола и дальше продолжают ходить, общаться, курить, дружить, покупать."},{"kind":"paragraph","text":"Небо и земля меняются местами, люди ходят по тучам и мечтают, чтобы они никогда не разошлись, иначе все упадут на солнце и от безысходности начнут играть им в футбол."},{"kind":"paragraph","text":"Обычный день. Город. Самара или Москва. Все в делах или отсутствии их. У одного мужчины на улице начинается эрекция. Член растёт, разрывает штаны, облака, устремляется дальше и превращается в межгалактический мост. По нему идут все, распевая песни и подбрасывая шапки вверх."},{"kind":"paragraph","text":"— Хочешь меня?"},{"kind":"paragraph","text":"— Но ты тоже мужчина."},{"kind":"paragraph","text":"— И что?"},{"kind":"paragraph","text":"— Надо с женщиной."},{"kind":"paragraph","text":"— Кто сказал?"},{"kind":"paragraph","text":"— Природа и бог."},{"kind":"paragraph","text":"— Наивный. Два члена — два минуса. Вместе дают плюс. Крест. Христа. Вечную жизнь."},{"kind":"paragraph","text":"— Я подумаю."},{"kind":"paragraph","text":"— Ну."},{"kind":"paragraph","text":"Бомж входит в трамвай, все орут:"},{"kind":"paragraph","text":"— Выходи!"},{"kind":"paragraph","text":"Он открывает рот, и из него начинают вылетать золотые монеты, сплошной поток, заваливающий людей. В конце слышится общий предсмертный вопль:"},{"kind":"paragraph","text":"— Достаточно, пощади!"},{"kind":"paragraph","text":"Бомж захлопывает варежку, но от этого золота становится только больше."},{"kind":"paragraph","text":"Груди — мороженое с вишенками или клубничками на концах, их едят мужчина и женщина, зализывают до рёбер, соединяются и целуются взасос, потому что превращение «её» в «него» — роман «Когда падают горы»."},{"kind":"paragraph","text":"Всякая женщина кричит: «Лизните мою промежность», но слышит это только она сама и делает сё."},{"kind":"paragraph","text":"В силу того, что у женщины нет члена, этот отсутствующий орган заменяют ей рука или нога."},{"kind":"paragraph","text":"Полиция арестовывает преступника, он вырывается, бежит, падает в открытый люк и оказывается на другой планете. Это история жизни, мира как такового, каждого на земле."},{"kind":"paragraph","text":"— Секс — это занятие сексом, потому — другое, совсем не то."},{"kind":"paragraph","text":"— Ты думаешь, люди постепенно растут целиком, в совокупности своей?"},{"kind":"paragraph","text":"— А как?"},{"kind":"paragraph","text":"— Сначала ходят по земле ноги, потом появляются половые органы, живот, грудь, шея и голова."},{"kind":"paragraph","text":"— В конце жизни?"},{"kind":"paragraph","text":"— Да. От этого человек умирает."},{"kind":"paragraph","text":"— Почему?"},{"kind":"paragraph","text":"— Потому что голова — кокон, из которого вылетает бабочка — бог."},{"kind":"paragraph","text":"Двери запирают для того, чтобы открыть стены, что случится однажды."},{"kind":"paragraph","text":"Девочка решает покончить с собой, идёт на железнодорожные пути и садится на них. Через полчаса или час поезд вылетает, несётся на неё и уходит в её вагину. Мир — роды наоборот."},{"kind":"paragraph","text":"«Клуб 27». Они умерли так, как живут другие. Миг самоубийства Кобейна — жизнь Фёдора Петровича или Вазгена Гургеновича от нуля до восьмидесяти лет, включающая в себя учёбу, работу, драки, любовь и секс. Но только не смерть, чьё отсутствие — курица без головы. Именно потому выстрел Курта был именно в неё."},{"kind":"paragraph","text":"Я иду на балкон и закуриваю сигарету длиною в жизнь. Отныне я буду только курить. Больше ничего. Никогда. Раз сигарета — стрела, вылетающая из лука — ребра — и в полёте превращающаяся в пулю — бычок, падающий на землю и пускающий в ней ростки: так кочевник становится земледельцем — не перемещается сам, а движет весь мир. Именно геоцентрическая модель победила со временем, конкретнее — анти-Галилей."}]'::jsonb,
  '2023-12-31T12:00:00.000Z'
)
